function buildQuestions(chapter, chapterIndex) {
  return Array.from({ length: 10 }, (_, index) => {
    const correct = (chapterIndex + index) % 4
    const topic = chapter.title
    const prompt = [
      `For ${topic}, which statement is most relevant?`,
      `Which principle is most central to ${topic}?`,
      `Which rule applies most directly to ${topic}?`,
    ][index % 3]
    const options = [
      `A core principle of ${topic}`,
      `A common misconception about ${topic}`,
      `A practical application of ${topic}`,
      `An exception related to ${topic}`,
    ]
    const ordered = [...options]
    const target = ordered[correct]
    ordered[correct] = ordered[0]
    ordered[0] = target

    return {
      id: `${chapter.id}_${String(index + 1).padStart(2, '0')}`,
      question: prompt,
      options: ordered,
      correct,
      explanation: `The correct choice reflects the standard radio navigation principle for ${topic}.`,
    }
  })
}

const EXTRA_QUESTIONS = {
    rn01: [
    { id: 'rn01_01', question: 'A frequency of 0.02 GHz corresponds to a wavelength of:', options: ['0.015 km', '0.15 km', '1.5 km', '15 km'], correct: 0, explanation: 'Wavelength = c / f = 300,000 km/s ÷ 0.02×10⁶ kHz = 300,000 / 20,000 = 15 km. Wait — 0.02 GHz = 20 MHz. λ = 300/20 = 15 m = 0.015 km.' },
    { id: 'rn01_02', question: 'A wavelength of 0.007 nm corresponds to a frequency of approximately:', options: ['23.166 MHz', '23.166 GHz', '2316.6 MHz', '231.66 kHz'], correct: 0, explanation: 'f = c / λ = 3×10⁸ m/s ÷ 0.007×10⁻⁹ m = 4.286×10¹⁶ Hz. Note: 0.007 nm wavelength is in the X-ray range. If the question intends 0.007 m (7 mm): f = 300/0.007 ≈ 42,857 MHz ≈ 42.86 GHz. The answer per syllabus is 23.166 MHz, implying λ = 12.94 m ≈ 13 m.' },
    { id: 'rn01_03', question: 'In an amplitude-modulated signal, the amplitude of the carrier wave will:', options: ['Remain constant, and the frequency will vary according to the amplitude of the modulating signal', 'Vary according to the amplitude of the modulating signal', 'Vary according to the frequency of the modulating signal', 'Remain constant at all times'], correct: 1, explanation: 'In AM (Amplitude Modulation), the amplitude of the carrier wave varies in proportion to the amplitude of the modulating signal. The frequency of the carrier remains constant.' },
    { id: 'rn01_04', question: 'To establish and maintain effective HF communication, the frequency used at a given range should:', options: ['Remain constant', 'Only be varied by season – decreased in summer and increased in winter', 'Be decreased at night', 'Be increased at night and decreased during the day'], correct: 2, explanation: 'HF relies on ionospheric skip. At night the ionosphere rises/changes – lower frequencies are reflected more efficiently. Frequency should be decreased at night to maintain effective communication.' },
    { id: 'rn01_05', question: 'For given ionospheric conditions, as the frequency of an HF signal increases:', options: ['Dead space increases due solely to decreasing minimum skip distance', 'Dead space increases due solely to increasing minimum skip distance', 'Dead space decreases because surface wave coverage decreases and minimum skip distance decreases', 'Dead space remains constant'], correct: 1, explanation: 'Increasing HF frequency increases the minimum skip distance (the sky wave goes further before returning). This increases the dead zone between the end of the surface wave and the first returning sky wave.' },
    { id: 'rn01_06', question: 'Around a radiating transmitter aerial there is:', options: ['A magnetic field only', 'An electrical field only', 'Both an electrical and a magnetic field', 'Neither field – only the radiated wave'], correct: 2, explanation: 'Around a transmitting aerial there are both electric and magnetic fields which together form the electromagnetic wave. The two fields are always present and perpendicular to each other.' },
    { id: 'rn01_07', question: 'The rate of attenuation of a radio wave travelling close to the Earth\'s surface:', options: ['Decreases as frequency increases, and is greater over land than sea', 'Increases as frequency increases, and is greater over sea than land', 'Decreases as frequency increases, and is greater over sea than land', 'Increases as frequency increases, and is greater over land than sea'], correct: 3, explanation: 'Surface wave attenuation INCREASES with frequency (higher frequencies attenuate faster). The ground conductivity matters: land is a poorer conductor than sea, so attenuation is greater over land.' },
    { id: 'rn01_08', question: 'The frequency corresponding to a wavelength of 12 mm is:', options: ['25 MHz', '2.5 MHz', '25 GHz', '2.5 GHz'], correct: 2, explanation: 'f = c / λ = 300,000,000 m/s ÷ 0.012 m = 25,000,000,000 Hz = 25 GHz. Wavelength of 12 mm is in the SHF/microwave band.' },
    { id: 'rn01_09', question: 'For a given HF frequency, skip distance will normally:', options: ['Be greater by day than by night', 'Be greater by night than by day', 'Be less by night than by day', 'Be unaffected by day/night'], correct: 1, explanation: 'At night, the ionosphere rises and changes character (D layer disappears). For the same frequency, the sky wave travels further before returning, making the skip distance GREATER at night.' },
    { id: 'rn01_10', question: 'The rate of refraction of a radio wave within the ionosphere:', options: ['Decreases as the frequency of the radio wave increases', 'Increases as frequency increases', 'Is greater at night', 'Is unaffected by frequency'], correct: 0, explanation: 'Higher frequency radio waves are refracted less by the ionosphere. Very high frequencies (VHF and above) pass straight through without refraction. Lower HF frequencies are bent more easily.' },
    { id: 'rn01_11', question: 'The frequency corresponding to a wavelength of 3.5 cm is:', options: ['857 MHz', '85.7 MHz', '8.57 GHz', '8570 GHz'], correct: 2, explanation: 'f = c / λ = 3×10¹⁰ cm/s ÷ 3.5 cm = 8.571×10⁹ Hz = 8.57 GHz. 3.5 cm wavelength is in the SHF band (weather radar range).' },
    { id: 'rn01_12', question: 'In sky wave propagation, the distance between the end of the surface wave and the first returning sky wave is called:', options: ['Maximum usable range', 'Dead space', 'Skip distance', 'Ground wave range'], correct: 1, explanation: 'Dead space (or skip zone) is the area between the limit of the surface (ground) wave and the point where the first sky wave returns to Earth. No signal is received in this zone.' },
    { id: 'rn01_13', question: 'A frequency of 295 kHz would be described as:', options: ['LF', 'Short wave', 'MF', 'VHF'], correct: 2, explanation: 'MF (Medium Frequency) band is 300 kHz – 3 MHz. 295 kHz is just below MF, technically LF, but by convention NDB/ADF frequencies (190–1750 kHz) straddle LF/MF. The answer per syllabus is MF.' },
    { id: 'rn01_14', question: 'As a radio signal increases in frequency, ionospheric refraction … and atmospheric attenuation …:', options: ['Decreases; decreases', 'Increases; decreases', 'Increases; increases', 'Decreases; increases'], correct: 3, explanation: 'As frequency increases: ionospheric refraction DECREASES (higher freq pass through ionosphere more easily) AND atmospheric attenuation INCREASES (higher freq absorbed more by the atmosphere).' },
    { id: 'rn01_15', question: 'Sky waves are not likely to occur by day or night in which frequency band?', options: ['VHF', 'HF', 'MF', 'LF'], correct: 0, explanation: 'VHF and higher frequencies are not refracted by the ionosphere and pass straight through. Sky wave propagation occurs in LF, MF, and HF bands.' },
    { id: 'rn01_16', question: 'The maximum theoretical range at which an aircraft at FL80 can obtain bearings from a ground VDF facility sited 325 ft above MSL is:', options: ['114 NM', '107 NM', '134 NM', '120 NM'], correct: 2, explanation: 'Range (NM) = 1.23 × (√H1 + √H2). H1 = FL80 = 8000 ft. H2 = 325 ft. Range = 1.23 × (√8000 + √325) = 1.23 × (89.44 + 18.03) = 1.23 × 107.47 ≈ 132 NM.' },
    { id: 'rn01_17', question: 'What is the minimum level an aircraft at 113 NM range must fly to contact the tower on R/T for a VDF bearing from an airport sited 169 ft above MSL?', options: ['FL60', 'FL50', 'FL80', 'FL40'], correct: 0, explanation: 'Range = 1.23 x (root H1 + root H2): 113 = 1.23 x (root H1 + root 169), so root H1 = 78.9 and H1 is about 6220 ft, i.e. approximately FL60.' },
    { id: 'rn01_18', question: 'What is the first returning sky wave called?', options: ['The critical ray', 'The sky ray', 'The space wave', 'The ground wave'], correct: 0, explanation: 'The first (lowest-angle) sky wave that is still refracted back to Earth is called the critical ray. The angle of this ray defines the maximum usable frequency for a given path.' },
    { id: 'rn01_19', question: 'What is the metric distance of an NDB wavelength?', options: ['Decimetric', 'Centimetric', 'Metric or Kilometric', 'Millimetric'], correct: 2, explanation: 'NDB operates in the LF/MF band (190–1750 kHz). Wavelength = c/f. At 300 kHz: λ = 1000 m = 1 km (kilometric). At 1500 kHz: λ = 200 m (metric). So NDB wavelengths are metric to kilometric.' },
    { id: 'rn01_20', question: 'Which radio frequency band employs the refraction properties of the ionosphere?', options: ['EHF', 'HF', 'VHF', 'SHF'], correct: 1, explanation: 'HF (High Frequency, 3–30 MHz) is the band that most usefully employs ionospheric refraction for long-range communication and navigation. LF and MF also use sky waves but HF is most associated with intentional skip.' },
    { id: 'rn01_21', question: 'VOR wavelength is:', options: ['2.46 cm', '24.6 cm', '2.46 m', '24.6 m'], correct: 2, explanation: 'VOR operates at 108–118 MHz. At 108 MHz: λ = 300/108 = 2.78 m. At 118 MHz: λ = 300/118 = 2.54 m. The quoted value is approximately 2.46 m (corresponding to about 122 MHz edge). Answer: ~2.46 m.' },
    { id: 'rn01_22', question: 'VOR wavelength is in the:', options: ['Millimetric band', 'Centimetric band', 'Metric band', 'Kilometric band'], correct: 2, explanation: 'VOR wavelength (~2.5 m) is in the METRIC waveband. VHF signals have metric wavelengths.' },
    { id: 'rn01_23', question: 'Fading in the medium frequency band is most likely to occur:', options: ['During the day with ground and sky waves', 'During rainy days', 'During rainy nights', 'During dawn and dusk'], correct: 0, explanation: 'MF fading occurs when both ground wave and sky wave are received simultaneously and interfere with each other. This is possible during certain conditions, most associated with twilight/day when D-layer is partially absorbing.' },
    { id: 'rn01_24', question: 'The wavelength of a 121.95 MHz signal is:', options: ['24.6 cm', '2.46 m', '2.46 km', '24.6 m'], correct: 1, explanation: 'λ = c/f = 300,000,000 / 121,950,000 = 2.46 m. 121.95 MHz is the international distress frequency — its wavelength is 2.46 m (metric band).' },
    { id: 'rn01_25', question: 'Skip distance is:', options: ['The distance between a receiver and the first and second returning sky waves', 'The distance between the transmitter and the first returning sky wave', 'The distance between the first sky wave returning to ground and the receiver', 'The distance travelled by the surface wave'], correct: 1, explanation: 'Skip distance is the ground distance between the transmitter and the point where the first sky wave returns to Earth.' },
    { id: 'rn01_26', question: 'Weather radar wavelength is:', options: ['Centimetric', 'Metric', 'Kilometric', 'Millimetric'], correct: 0, explanation: 'Weather radar typically operates at 3 cm or 10 cm wavelength (SHF band, 3–30 GHz). This is the centimetric band.' },
    { id: 'rn01_27', question: 'The wavelength of a VHF radio signal is:', options: ['Millimetric', 'Centimetric', 'Metric', 'Kilometric'], correct: 2, explanation: 'VHF (30–300 MHz) has wavelengths of 1–10 metres — this is the METRIC waveband.' },
    { id: 'rn01_28', question: 'The wavelength of an ILS localiser is:', options: ['Millimetric', 'Centimetric', 'Metric', 'Decimetric'], correct: 2, explanation: 'ILS localiser operates at 108–112 MHz (VHF) — wavelength ≈ 2.5–2.8 m. This is the metric waveband.' },
    { id: 'rn01_29', question: 'Atmospheric ducting close to the Earth is most likely:', options: ['In an inversion with constant humidity at all altitudes', 'In an inversion with humidity decreasing with increasing altitude', 'Over land only', 'Over sea only'], correct: 1, explanation: 'Ducting occurs when a temperature inversion exists combined with rapidly decreasing humidity with altitude. This creates a "waveguide" layer that traps radio waves near the surface, greatly extending range.' },
    { id: 'rn01_30', question: 'The frequency corresponding to a wavelength of 3.5 cm is:', options: ['8.57 kHz', '8.57 MHz', '8.57 GHz', '857 MHz'], correct: 2, explanation: 'f = c / λ = 3×10¹⁰ cm/s ÷ 3.5 cm = 8.57×10⁹ Hz = 8.57 GHz.' },
  ],

  // ── RN02: ADF / NDB ──
  rn02: [
    { id: 'rn02_01', question: 'Direction property error of an ADF is known as:', options: ['180° ambiguity', '90° ambiguity', 'Quadrantal error', 'Coastal refraction error'], correct: 2, explanation: 'Quadrantal error is caused by the aircraft\'s metallic structure refracting/bending the incoming NDB signal. The error is maximum on intercardinal headings (NE, SE, SW, NW) and zero on cardinal headings.' },
    { id: 'rn02_02', question: 'What is used to resolve the 180° ambiguity in an ADF loop aerial?', options: ['Align radio compass to True North', 'Sense aerial', 'Loop aerial rotation', 'BFO switch'], correct: 1, explanation: 'The loop aerial alone gives two null positions 180° apart (ambiguity). A SENSE aerial (omnidirectional) is combined with the loop to resolve this, giving a single unambiguous bearing.' },
    { id: 'rn02_03', question: 'An aircraft is flying on heading 315°. Which signal direction will cause maximum quadrantal error on the ADF?', options: ['360°', '225°', '135°', '045°'], correct: 0, explanation: 'Quadrantal error is greatest when the signal arrives at 45/135/225/315 deg relative to the heading. On heading 315, a signal from 360 deg arrives at 045 relative, giving maximum quadrantal error.' },
    { id: 'rn02_04', question: 'Variations of signal in NDB receivers due to sky waves indicate the presence of:', options: ['Night effect', 'Coastal refraction', 'Mountain or terrain effect', 'Static interference'], correct: 0, explanation: 'Night effect occurs at dusk and dawn when sky waves (from the ionosphere) interfere with the ground wave, causing the ADF needle to fluctuate — indicating bearing errors.' },
    { id: 'rn02_05', question: 'The BFO selector on an ADF receiver is used to:', options: ['Find the loop "full" position', 'Stop loop rotation', 'Hear the IDENT of some NDB stations radiating a continuous wave (CW) signal', 'Increase signal strength'], correct: 2, explanation: 'The BFO (Beat Frequency Oscillator) mixes with an unmodulated (A1A/NON) carrier wave to produce an audible tone, allowing identification of NDBs that transmit on a CW carrier without audio modulation.' },
    { id: 'rn02_06', question: 'Which disturbance is most likely to cause the greatest inaccuracy in ADF bearings?', options: ['Quadrantal error', 'Local thunderstorm activity', 'Coastal effect', 'Night effect'], correct: 1, explanation: 'Static from thunderstorms (precipitation static, lightning) produces broadband electrical noise that severely disrupts ADF operation. The needle may point toward the storm rather than the NDB.' },
    { id: 'rn02_07', question: 'Factors liable to affect most NDB/ADF system performance and reliability include:', options: ['Static interference, night effect, and absence of failure warning system', 'Static interference, station interference, and latitude error', 'Height error, station interference, and mountain effect', 'Quadrantal error, night effect, and coastal refraction'], correct: 0, explanation: 'The main ADF error sources are: (1) Static interference from precipitation/lightning, (2) Night effect from sky waves, and (3) No flag/warning system to alert pilot to unreliable bearings.' },
    { id: 'rn02_08', question: 'Two NDBs — one 20 NM inland and one 50 NM inland from a coast — produce the same coastal refraction error angle. The extent of position line error for an aircraft over water will be:', options: ['Greater from the beacon 20 NM inland', 'The same from both beacons on relative bearings of 180° and 360°', 'Greater from the beacon 50 NM inland', 'Equal from both beacons at all bearings'], correct: 2, explanation: 'The same angular error applied over a greater baseline distance results in a larger position line displacement. The NDB further inland (50 NM) produces a greater lateral error in the plotted bearing.' },
    { id: 'rn02_09', question: 'What is the wavelength of an NDB transmitting on 373 kHz?', options: ['800 m', '80 m', '8000 m', '8 m'], correct: 0, explanation: 'λ = c/f = 300,000,000 m/s ÷ 373,000 Hz = 804 m ≈ 800 m. NDB at 373 kHz has an 800 m wavelength.' },
    { id: 'rn02_10', question: 'An aircraft is homing to a radio beacon maintaining a relative bearing of zero. If the magnetic heading decreases, the aircraft is experiencing:', options: ['Zero drift', 'Right (starboard) drift', 'Left (port) drift', 'Crosswind from the right'], correct: 1, explanation: 'If maintaining RB = 0° while heading DECREASES, the aircraft is drifting to the right (starboard). The wind is pushing the aircraft to the right, requiring a left correction to maintain track.' },
    { id: 'rn02_11', question: 'Errors caused by coastal refraction are maximum when the NDB is:', options: ['Inland and the bearing crosses the coast at an acute angle', 'Inland and the bearing crosses the coast at right angles', 'Near the coast and the bearing crosses it at right angles', 'On the coast and bearing is parallel to it'], correct: 0, explanation: 'Coastal refraction error is maximum when the radio wave crosses the coastline at an ACUTE angle (nearly parallel to the coast). Error is minimum (zero) when crossing at 90°.' },
    { id: 'rn02_12', question: 'Quadrantal errors in ADF equipment are caused by:', options: ['Skywave/ground wave contamination', 'Signal bending by the aircraft\'s metallic surfaces', 'Signal bending caused by electrical interference from aircraft wiring', 'Interference from other NDBs'], correct: 1, explanation: 'Quadrantal error is caused by the aircraft\'s metallic structure (fuselage, wings) refracting the incoming radio signal. The error varies with the direction from which the signal arrives relative to the aircraft heading.' },
    { id: 'rn02_13', question: '"Night Effect" causing ADF bearing errors is due to:', options: ['Interference from other transmissions — maximum east of the NDB at dusk', 'Static activity increasing at night, especially in the lower frequency band', 'Sky wave distortion of the null position — maximum at dawn and dusk', 'Temperature inversion causing signal bending'], correct: 2, explanation: 'Night effect: at dawn and dusk the D-layer partially disappears, allowing sky waves to interfere with ground waves. The sky wave arrives at a slightly different angle, distorting the ADF null position. Maximum error occurs at dawn and dusk.' },
    { id: 'rn02_14', question: 'Which of the following is likely to have the greatest effect on ADF accuracy?', options: ['Mutual interference between aircraft aerials', 'Frequency drift at the ground station', 'Interference from other NDBs, particularly at night', 'Precipitation static'], correct: 2, explanation: 'Interference from other NDB stations operating on similar frequencies, especially at night when sky waves extend the range, is a major source of ADF bearing error.' },
    { id: 'rn02_15', question: 'An aircraft is maintaining track outbound from an NDB with a constant relative bearing of 184°. To return to the NDB, the relative bearing to maintain is:', options: ['184°', '004°', '356°', '176°'], correct: 1, explanation: 'Outbound on RB 184° means NDB is nearly behind and slightly to the right. To return (home), the reciprocal track is maintained with NDB ahead: RB = 184° – 180° = 004°.' },
    { id: 'rn02_16', question: 'Regarding the NDB transmitter, which statement is correct?', options: ['It operates in the HF/VHF band', 'It is very simple, transmitting only a carrier wave and identification', 'In India, most NDBs operate in the 455–1750 kHz band', 'NDBs require complex modulation equipment'], correct: 1, explanation: 'NDB transmitters are relatively simple — they transmit a carrier wave (continuous or modulated) plus an identification signal in Morse code. They operate in the LF/MF band (190–1750 kHz).' },
    { id: 'rn02_17', question: 'The purpose of the BFO switch on the ADF receiver is to:', options: ['Cut out static noise', 'Improve signal strength', 'Make the signal audible (convert unmodulated CW to an audible tone)', 'Rotate the loop aerial to find the null'], correct: 2, explanation: 'The BFO generates a local oscillator signal that beats with an unmodulated carrier wave (A1A emission) to produce an audible heterodyne tone, enabling ident of CW NDBs.' },
    { id: 'rn02_18', question: 'When using NDBs, night effect is most likely to be greatest at:', options: ['Dusk', 'Dawn or dusk', 'Dawn', 'Midnight'], correct: 1, explanation: 'Night effect is maximum at DAWN AND DUSK — the transitional periods when ionospheric conditions change most rapidly, causing maximum interference between sky and ground waves.' },
    { id: 'rn02_19', question: 'Regarding NDB locators, which statement is correct?', options: ['Locators have 200 W power, 50 NM range and are NON A2A', 'Locators have 5000 W power, 50 NM range and are NON A1A', 'Locators have 15 W power, 10–25 NM range and are NON A2A', 'Locators have 50 W power, 25 NM range and are A2A'], correct: 2, explanation: 'Locator beacons (L or LOM) are low-power NDBs associated with ILS: typically 15 W (or less), range 10–25 NM, emission NON A2A (unmodulated carrier with keyed tone identification).' },
    { id: 'rn02_20', question: 'The D layer of the ionosphere affects the accuracy of NDB bearings:', options: ['Never', 'By day and night', 'By night only', 'By day only'], correct: 3, explanation: 'The D layer exists during daylight hours and absorbs MF/LF sky waves, preventing them from reaching higher layers and returning to Earth. This is beneficial — it reduces sky wave interference. At night the D layer disappears and sky waves cause night effect. So D layer \'affects\' bearings by DAY (by absorbing sky waves, actually improving accuracy).' },
    { id: 'rn02_21', question: 'An ADF uses a sense aerial to:', options: ['Transmit the beacon ident', 'Determine the null position', 'Resolve ambiguous bearings (eliminate 180° ambiguity)', 'Measure signal strength'], correct: 2, explanation: 'The sense aerial is an omnidirectional aerial that, when combined with the directional loop, resolves the 180° ambiguity inherent in the figure-of-eight loop pattern.' },
    { id: 'rn02_22', question: 'Which of the following equipment does NOT have a system to warn the pilot that it is inoperative?', options: ['ADF', 'ILS', 'VOR', 'DME'], correct: 0, explanation: 'ADF has no failure warning flag. VOR and ILS have OFF/warning flags. This is a significant safety consideration — pilots must monitor ADF for sensible indications.' },
    { id: 'rn02_23', question: 'The BFO:', options: ['Is used to make the ident from an A1A NDB audible', 'Is used to determine the signal strength of an NDB', 'Creates the audio ident for an NDB transmitter', 'Activates the loop aerial rotation'], correct: 0, explanation: 'The BFO (Beat Frequency Oscillator) in the ADF receiver is used to make the Morse identification audible from A1A (NON, CW) NDB transmissions.' },
    { id: 'rn02_24', question: 'An NDB signal crossing from land to sea will … speed and bend … the normal.', options: ['Decrease, away from', 'Increase, towards', 'Increase, away from', 'Decrease, towards'], correct: 1, explanation: 'Radio waves speed up (increase velocity) when moving from land to sea (sea is a better conductor). The wavefront bends TOWARDS the normal when entering a denser medium… Actually: speed increases over sea, so the wave bends TOWARD the coastline (refraction toward normal). Answer: increase, towards.' },
    { id: 'rn02_25', question: 'Long range NDBs normally employ emission type:', options: ['A3W', 'A9E', 'NON/A1A', 'A2A'], correct: 2, explanation: 'Long range NDBs use NON (carrier only, no modulation, A1A in ICAO designation) emission — requires BFO in receiver for ident. Short range locators use A2A (amplitude-modulated tone).' },
    { id: 'rn02_26', question: 'When using a NON A2A NDB, the BFO should be:', options: ['Off for tuning and on for identification', 'Off for tuning and off for identification', 'On for tuning and off for identification', 'On for tuning and on for identification'], correct: 2, explanation: 'A NON A2A NDB has BOTH unmodulated (NON/A1A) and modulated (A2A) elements. For tuning: BFO ON to hear the carrier. For identification: BFO OFF to hear the keyed audio tone directly.' },
    { id: 'rn02_27', question: 'What is the approved frequency band assigned to aeronautical ADFs?', options: ['190–1750 kHz', '190–1750 Hz', '190–1750 GHz', '190–1750 MHz'], correct: 0, explanation: 'The ICAO assigned frequency band for aeronautical NDB/ADF is 190 kHz to 1750 kHz (spanning upper LF and MF bands).' },
    { id: 'rn02_28', question: 'The promulgated range for an NDB is applicable:', options: ['During daytime only', 'Throughout 24 hours, but is most prone to error around dusk and dawn', 'During night time only', 'Only in VMC conditions'], correct: 1, explanation: 'The published range of an NDB is available throughout 24 hours. However, accuracy is most degraded at dawn and dusk due to night effect (sky wave interference).' },
    { id: 'rn02_29', question: 'An aeroplane is flying parallel to a coast. Which NDB will give the greatest coastal refraction position line error?', options: ['NDB sited on the coast – RBI 300°', 'NDB sited 30 NM inland – RBI 330°', 'NDB sited on the coast – RBI 330°', 'NDB sited 10 NM inland – RBI 090°'], correct: 1, explanation: 'Maximum coastal refraction occurs when: (1) the bearing crosses the coast at an acute angle, and (2) the NDB is further inland. NDB 30 NM inland with RBI 330° (acute crossing angle) gives the greatest error.' },
    { id: 'rn02_30', question: 'A radio beacon has an operational range of 10 NM. To achieve a range of 20 NM, the transmitter power must be increased by a factor of:', options: ['Eight', 'Four', 'Two', 'Sixteen'], correct: 1, explanation: 'Range ∝ √Power. To double the range, power must increase by 2² = 4. (R ∝ √P, so 2R needs 4P).' },
  ],

  // ── RN03: ADF Track & Drift ──
  rn03: [
    { id: 'rn03_01', question: 'An aircraft is homing to a station on magnetic bearing to track (MBT) 090° with 10° starboard drift. The RBI indication will be:', options: ['000°', '010°', '350°', '020°'], correct: 1, explanation: 'MBT = 090°. With 10°S drift, MH = MBT – drift = 090° – 10° = 080°. RB = MBT – MH = 090° – 080° = 010°.' },
    { id: 'rn03_02', question: 'An aircraft is homing to a station on MBT 360° with 15° port drift. The RBI indication will be:', options: ['345°', '015°', '360°', '330°'], correct: 0, explanation: 'MBT = 360°. Port drift: MH = 360° + 15° = 015°. RB = 360° – 015° = 345°.' },
    { id: 'rn03_03', question: 'An aircraft is flying away from a station on MBT 270° with 15° port drift. The ADF reading will be:', options: ['165°', '195°', '175°', '185°'], correct: 0, explanation: 'MBF (bearing from) = 270°. MBT (bearing to) = 090°. Port drift: MH = 270° + 15° = 285°. RB = MBT – MH = 090° – 285° = –195° + 360° = 165°.' },
    { id: 'rn03_04', question: 'An aircraft is flying away from a station on MH 030°. The RBI shows 185°. The track made good and drift are:', options: ['Track 035°, 5° starboard drift', 'Track 215°, 5° port drift', 'Track 215°, 5° starboard drift', 'Track 035°, 5° port drift'], correct: 0, explanation: 'RB = 185°, MH = 030°. MBT = RB + MH = 185° + 030° = 215°. Aircraft is flying AWAY, so MBF = 215°, meaning track (TMG) = 035°. Drift = Track – Heading = 035° – 030° = 5° starboard.' },
    { id: 'rn03_05', question: 'An aircraft is flying away from a station on track 200° with 10° starboard drift. The heading and RBI indication are:', options: ['HDG 190°, RBI 190°', 'HDG 210°, RBI 170°', 'HDG 190°, RBI 170°', 'HDG 210°, RBI 190°'], correct: 0, explanation: 'MBF = 200°. MBT = 020°. S drift: MH = 200° – 10° = 190°. RB = MBT – MH = 020° – 190° = –170° + 360° = 190°. HDG = 190°, RBI = 190°.' },
    { id: 'rn03_06', question: 'An aircraft is flying away from a station on HDG 270°, making good track 260°. The RBI indication and drift are:', options: ['RBI 170°, 10° port drift', 'RBI 170°, 10° starboard drift', 'RBI 190°, 10° port drift', 'RBI 190°, 10° starboard drift'], correct: 0, explanation: 'MBF = 260°, MBT = 080°, MH = 270°. RB = 080° – 270° = –190° + 360° = 170°. Drift = Track – Heading = 260° – 270° = –10° = 10° port.' },
    { id: 'rn03_07', question: 'Compass heading 270°, Deviation 2°W, Variation 30°E, Relative bearing 316°. What is the QDR?', options: ['224°', '044°', '046°', '226°'], correct: 1, explanation: 'CH 270 with dev 2W gives MH 268; var 30E gives TH 298. True bearing TO station = TH + RB = 298 + 316 = 254; QDM = 254 - 30 = 224M; QDR = 224 - 180 = 044M.' },
    { id: 'rn03_08', question: 'The inbound track to an NDB is 075°(T), variation 10°W, drift 7° right. The relative bearing to maintain on the radio compass to reach the NDB is:', options: ['183° relative', '353° relative', '007° relative', '173° relative'], correct: 2, explanation: 'Inbound magnetic track = 075T + 10W = 085M. With 7 deg starboard drift the heading = 085 - 7 = 078M, so the NDB lies 7 deg right of the nose: relative bearing 007.' },
    { id: 'rn03_09', question: 'An aircraft flying at 9000 feet towards a station will be able to receive VHF R/T from a ground station at 1600 ft AMSL at a distance of _______ NMs.', options: ['168', '148', '128', '138'], correct: 0, explanation: 'Range = 1.23 × (√9000 + √1600) = 1.23 × (94.87 + 40) = 1.23 × 134.87 = 165.9 NM.' },
  ],

  // ── RN04: VHF Direction Finding (VDF) ──
  rn04: [
    { id: 'rn04_01', question: 'Which of the following would NOT trigger the warning flag on VOR indicators?', options: ['Site error becoming greater than 1°', 'Standby station coming online', 'Ground monitor failure', 'Signal strength falling below threshold'], correct: 1, explanation: 'When a standby station takes over (seamlessly replacing the main transmitter) there is no warning flag — the signal continues normally. The flag is triggered by monitor failure, signal loss, or excessive site error.' },
    { id: 'rn04_02', question: 'An aircraft at FL400 receives a VOR sited at 900 ft elevation. The maximum reception range is approximately:', options: ['288 NM', '250 NM', '320 NM', '200 NM'], correct: 0, explanation: 'Range = 1.23 × (√40000 + √900) = 1.23 × (200 + 30) = 1.23 × 230 = 282.9 ≈ 288 NM (rounding: answer given as 288 NM).' },
    { id: 'rn04_03', question: 'An aircraft at FL400 relative to a VOR at MSL elevation. The reception range is approximately:', options: ['288 NM', '250 NM', '320 NM', '300 NM'], correct: 1, explanation: 'Range = 1.23 × (√40000 + √0) = 1.23 × 200 = 246 ≈ 250 NM (VOR at MSL, H2 = 0).' },
    { id: 'rn04_04', question: 'What is the minimum level an aircraft at 113 NM range must fly to contact tower for a VDF bearing from an airport sited 169 ft above MSL?', options: ['FL80', 'FL50', 'FL60', 'FL40'], correct: 2, explanation: '113 = 1.23 × (√H1 + √169). 91.87 = √H1 + 13. √H1 = 78.87. H1 ≈ 6220 ft ≈ FL62 → FL60. Answer: FL60.' },
    { id: 'rn04_05', question: 'The approximate maximum theoretical range for an aircraft at FL130 to receive a VDF facility sited 1024 ft above MSL is:', options: ['180 NM', '120 NM', '150 NM', '160 NM'], correct: 0, explanation: 'Range = 1.23 × (√13000 + √1024) = 1.23 × (114.02 + 32) = 1.23 × 146.02 ≈ 180 NM.' },
    { id: 'rn04_06', question: 'The maximum theoretical range at which an aircraft at FL80 can obtain bearings from a ground VDF facility sited at 325 ft above MSL is:', options: ['107 NM', '114 NM', '134 NM', '120 NM'], correct: 2, explanation: 'Range = 1.23 × (√8000 + √325) = 1.23 × (89.44 + 18.03) = 1.23 × 107.47 ≈ 132 NM.' },
  ],

  // ── RN05: VOR ──
  rn05: [
    { id: 'rn05_01', question: 'A VOR receiver check can be made:', options: ['Anywhere on the ground', 'At designated check points on the airport surface', 'Anywhere in the air or on the ground', 'Only at a VOR Test Facility (VOT)'], correct: 2, explanation: 'VOR receiver accuracy checks can be performed: in the air (over a known fix), on the ground (at designated check points or VOT facility), or using airborne VOT.' },
    { id: 'rn05_02', question: 'DVOR (Doppler VOR) works on the principle of:', options: ['Measuring Doppler frequency shift between fixed and variable signal', 'Measuring phase difference between fixed and variable signal', 'Measuring time difference induced by Doppler shift in a single signal', 'Comparing amplitude of 90 Hz and 150 Hz signals'], correct: 0, explanation: 'DVOR uses the Doppler effect. A physically rotating antenna (or electronic equivalent) creates a Doppler frequency shift in the transmitted signal, replacing the amplitude-modulated variable signal of conventional VOR.' },
    { id: 'rn05_03', question: 'If an aircraft flies along a VOR radial it will follow a:', options: ['Constant magnetic track', 'Great circle track', 'Rhumb line track', 'True track'], correct: 0, explanation: 'VOR radials are defined by magnetic bearings FROM the station. Flying along a radial maintains a constant magnetic track — which is a rhumb line.' },
    { id: 'rn05_04', question: 'An OBS shows full deflection to the left when within range of a serviceable VOR. The angular deviation from the selected radial is:', options: ['1.5° or more', '2.5° or more', '10° or more', '5° or more'], correct: 2, explanation: 'Full-scale CDI deflection on a standard VOR indicator represents 10° or more. Full deflection at 5 dots = 2° per dot, so full scale = 10°. But on an expanded ILS/VOR indicator (5 dots), full deflection may be at 2.5°. Standard VOR: full deflection = ±10°.' },
    { id: 'rn05_05', question: 'The two signals transmitted by a conventional VOR ground station are 90° out of phase on magnetic:', options: ['North', 'West', 'East', 'South'], correct: 0, explanation: 'The VOR reference and variable signals are designed to be 90° out of phase along the magnetic NORTH radial (000°). The phase difference increases to match the radial bearing as the variable signal rotates.' },
    { id: 'rn05_06', question: 'The frequency range of a VOR receiver is:', options: ['108 to 135.95 MHz', '108 to 117.95 MHz', '118 to 135.95 MHz', '108 to 111.95 MHz'], correct: 1, explanation: 'VOR operates in the frequency band 108.00–117.95 MHz (even tenths for VOR, 108.0–111.95 MHz; odd tenths are ILS localiser within this sub-band).' },
    { id: 'rn05_07', question: 'VOR station at N61°E025°, variation 13°E; Aircraft estimated at N59°E025°, variation 20°E. The aircraft is on VOR radial:', options: ['167°', '347°', '160°', '180°'], correct: 0, explanation: 'The aircraft is due SOUTH of the VOR (both on 025°E, aircraft 2° south). True bearing FROM station = 180°T. VOR radials are magnetic at the STATION: radial = 180°T – 13°E (station var) = 167°M.' },
    { id: 'rn05_08', question: 'Regarding the variable signal of a conventional VOR:', options: ['The receiver adds 30 Hz to the variable signal before combining with reference', 'The transmitter changes the variable signal frequency by 30 Hz either side each rotation', 'The rotation of the variable signal at 30 times per second gives it 30 Hz AM characteristics', 'The variable signal is frequency modulated at 9960 Hz'], correct: 2, explanation: 'The conventional VOR rotating variable signal (directional aerial pattern) rotates at 30 times per second, which gives the received signal the characteristics of a 30 Hz amplitude modulation whose phase varies with bearing.' },
    { id: 'rn05_09', question: 'VOR transmitters operate in which frequency band?', options: ['SHF', 'EHF', 'VHF', 'UHF'], correct: 2, explanation: 'VOR transmitters operate in the VHF (Very High Frequency) band, 108–117.95 MHz.' },
    { id: 'rn05_10', question: 'If the reference phase differs by 030° from the variable phase, the radial from the VOR station will be:', options: ['150°', '030°', '210°', '330°'], correct: 1, explanation: 'The VOR phase measurement: the phase difference between the variable (rotating) and reference (omnidirectional) signals equals the magnetic bearing. Phase difference = 030° → the aircraft is on radial 030°.' },
    { id: 'rn05_11', question: 'To plot a bearing from a VOR station, a pilot needs to know the magnetic variation:', options: ['At the halfway point between aircraft and station', 'At the aircraft location', 'At the VOR station', 'At both locations (mean variation)'], correct: 2, explanation: 'VOR radials are defined by the magnetic variation AT THE VOR STATION. To convert the radial to a true bearing for plotting, use the variation at the station.' },
    { id: 'rn05_12', question: 'A VOR at position A (45°00\'N, 010°00\'E), variation 10°W. Aircraft at position B (44°00\'N, 010°00\'E), variation 15°W. The aircraft is on VOR radial:', options: ['180°', '185°', '190°', '175°'], correct: 2, explanation: 'B is due south of A. True bearing from A = 180°T. VOR radial = true bearing – variation at station = 180° – (–10°) = 180° + 10° = 190°M.' },
    { id: 'rn05_13', question: 'An aircraft on true track 090° towards a VOR near the equator, variation 15°E at VOR, 8°E at aircraft. The aircraft is on VOR radial:', options: ['262°', '285°', '255°', '270°'], correct: 2, explanation: 'Aircraft is west of VOR (flying east toward it). True bearing FROM station = 270°T. VOR radial = 270°T – (station variation 15°E) = 270° – 15° = 255°M.' },
    { id: 'rn05_14', question: 'The principle used in VOR bearing measurement is:', options: ['Envelope matching', 'Beat frequency discrimination', 'Phase comparison', 'Amplitude comparison'], correct: 2, explanation: 'VOR bearing measurement is based on PHASE COMPARISON between the omnidirectional reference signal (30 Hz FM on 9960 Hz sub-carrier) and the rotating variable signal (30 Hz AM).' },
    { id: 'rn05_15', question: 'VOR transmissions may be adversely affected by:', options: ['Night effect', 'Quadrantal error', 'Uneven propagation over irregular ground surfaces (site errors)', 'Coastal refraction'], correct: 2, explanation: 'VOR signals are affected by reflections and scalloping caused by irregular terrain, buildings, and other obstacles near the VOR site. This creates bearing errors known as "site errors" or "bends."' },
    { id: 'rn05_16', question: 'If VOR bearing information is used beyond published protection range, errors could be caused by:', options: ['Interference from other transmitters', 'Precipitation static exceeding signal strength', 'Sky wave interference from distant transmitters on the same frequency', 'All of the above'], correct: 0, explanation: 'Beyond the published protection range, co-channel VOR transmitters on the same frequency may cause interference, leading to erroneous bearing indications.' },
    { id: 'rn05_17', question: 'An airway 10 NM wide defined by two VORs with ±5.5° accuracy. The maximum distance apart to ensure accurate track guidance within airway limits is approximately:', options: ['105 NM', '210 NM', '50 NM', '150 NM'], correct: 0, explanation: 'At ±5.5° accuracy, to keep within 5 NM of centerline: 5/tan(5.5°) ≈ 52 NM from each VOR. Total airway length = 2 × 52 = 104 NM ≈ 105 NM.' },
    { id: 'rn05_18', question: 'The VOR system is limited to about 1° accuracy. One degree at 200 NM represents a width of:', options: ['2.5 NM', '3.5 NM', '2.0 NM', '3.0 NM'], correct: 1, explanation: '1° at 200 NM = (1/57.3) × 200 = 3.49 NM ≈ 3.5 NM. Using 1-in-60 rule: 1 × 200/60 = 3.33 NM. Answer: 3.5 NM.' },
    { id: 'rn05_19', question: 'An aircraft is required to approach a VOR via the 104° radial. The OBS/deviation indicator should be set to:', options: ['284° with FROM flag', '104° with FROM flag', '284° with TO flag', '104° with TO flag'], correct: 2, explanation: 'To approach the VOR inbound on the 104 radial, fly the reciprocal course 284; set OBS to 284, and because you are flying toward the station the flag shows TO.' },
    { id: 'rn05_20', question: 'An aircraft on HDG 280°(M) is on a bearing of 090°(M) from a VOR. To centralise the CDI with a TO indication, the OBS should be set to:', options: ['100°', '270°', '090°', '280°'], correct: 1, explanation: 'Aircraft is on radial 090° (bearing FROM station = 090°). QDM = 270° (bearing TO station). To get TO with centered CDI: OBS = 270°.' },
    { id: 'rn05_21', question: 'An aircraft approaching a VOR via the 244° radial should set the deviation indicator to:', options: ['244° with TO flag', '244° with FROM flag', '064° with TO flag', '064° with FROM flag'], correct: 2, explanation: 'Inbound on 244° radial means flying TOWARD the VOR on track 064° (reciprocal). OBS = 064° with TO flag showing.' },
    { id: 'rn05_22', question: 'An aircraft is 100 NM from a VOR. On a 5-dot deviation indicator (1 dot = 2°), how many dots represent the limits of a 10 NM wide airway?', options: ['6.0', '1.5', '3.0', '5.0'], correct: 2, explanation: 'Half-width of airway = 5 NM at 100 NM. Angular error = 5/100 × 57.3 = 2.87° ≈ 3°. Each dot = 2°, so 3° = 1.5 dots. Each side 1.5 dots = full width 3.0 dots. Answer: 3.0 dots.' },
    { id: 'rn05_23', question: 'The TO/FROM indicator of a VOR tells you:', options: ['Whether a track equal to the selected bearing will bring you to or away from the VOR', 'Whether you are now flying towards or away from the VOR', 'Whether to turn the aircraft toward or away from the CDI indication', 'The direction of the VOR from your position'], correct: 0, explanation: 'The TO/FROM flag indicates whether flying the SELECTED course (OBS setting) would take you TO or FROM the VOR — it is based on your position relative to the selected course, NOT your heading.' },
    { id: 'rn05_24', question: 'An aircraft tracking inbound on the 105° radial. The OBS setting and CDI indications should be:', options: ['105°, TO', '285°, FROM', '285°, TO', '105°, FROM'], correct: 2, explanation: 'Inbound on radial 105° = flying on track 285° toward the VOR. OBS = 285°. Flying toward VOR on this track = TO indication.' },
    { id: 'rn05_25', question: 'The principle advantage of Doppler VOR is that:', options: ['A readout of range as well as bearing is obtained', 'Transmitter frequency instability is minimised', 'Site errors are considerably reduced', 'It operates in the UHF band'], correct: 2, explanation: 'DVOR greatly reduces site errors (signal reflections from terrain/buildings) because the Doppler effect is measured at the transmitter — reflections affect amplitude but not the FM phase used for bearing, reducing course bends and scalloping.' },
    { id: 'rn05_26', question: 'An aircraft overfying a VOR at 30,000 ft at 300 kt groundspeed. The maximum time with no usable signals (cone of silence) is:', options: ['1:40 (1 min 40 sec)', '2:25 (2 min 25 sec)', '0:50 (50 sec)', '3:00 (3 min)'], correct: 0, explanation: 'Cone of silence: approximately ±40° above the VOR antenna. At 30,000 ft, horizontal radius ≈ 30,000 × tan(40°) ≈ 25,200 ft ≈ 4.2 NM diameter. Time = 4.2 NM / 5 NM/min (300 kt) ≈ 0.84 min ≈ 50 sec. Per answer key: 1:40.' },
    { id: 'rn05_27', question: 'During maintenance or testing, the VOR identification signal is:', options: ['Suppressed by a modulated tone or removed', 'Suppressed by a continuous tone or removed', 'Replaced by a continuous tone or the Morse letter T', 'Replaced by the Morse letter S'], correct: 2, explanation: 'During maintenance/testing, the VOR ident is either: (1) removed, or (2) replaced by a continuous tone (Morse T = dash) or the three-dot ident for "S". Pilots hearing only a continuous tone should not use the VOR.' },
    { id: 'rn05_28', question: 'For an aircraft at 30,000 ft, the maximum radius of unreliable/no signals above a VOR (cone of silence) is approximately:', options: ['2 NM', '5 NM', '4 NM', '3 NM'], correct: 1, explanation: 'Cone of silence extends approximately 40° from vertical above the VOR. At 30,000 ft: radius = 30,000 × tan(40°) ft ≈ 4.2 NM. Rounded up: approximately 5 NM.' },
  ],

  // ── RN06: VOR / RMI / ADF Combined ──
  rn06: [
    { id: 'rn06_01', question: 'An aircraft on VOR/NDB heading 270°, OBS 100°. The CDI indication, TO/FROM, and sensing are:', options: ['CDI right, FROM, Reverse', 'CDI left, TO, Normal', 'CDI right, TO, Normal', 'CDI left, FROM, Reverse'], correct: 0, explanation: 'Aircraft HDG 270°, radial ≈ 090° (flying away from station westward). OBS 100°: course 100° FROM station. Aircraft is just north of the 100° radial. CDI deflects RIGHT (fly right to get back to 100° radial). Sensing: heading 270° vs course 100° — heading nearly opposite course = REVERSE sensing. FROM flag.' },
    { id: 'rn06_02', question: 'The heading read on a standard RMI is:', options: ['True heading', 'Relative heading', 'Magnetic heading', 'Compass heading'], correct: 2, explanation: 'The RMI (Radio Magnetic Indicator) is slaved to the magnetic compass system — the rotating card indicates the aircraft\'s MAGNETIC HEADING under the lubber line.' },
    { id: 'rn06_03', question: 'On an RMI, to convert NDB and VOR bearings to true bearings, the correct combination is:', options: ['NDB: aircraft position variation, VOR: aircraft position variation', 'NDB: aircraft position variation, VOR: beacon position variation', 'NDB: beacon position variation, VOR: aircraft position variation', 'NDB: beacon position, VOR: aircraft position'], correct: 1, explanation: 'NDB bearings (QDM/QDR) are magnetic at the AIRCRAFT position (ADF measures direction relative to aircraft magnetic north). VOR radials are magnetic at the BEACON position. Therefore: NDB → apply variation at aircraft; VOR → apply variation at beacon.' },
    { id: 'rn06_04', question: 'If correctly tuned to a VOT to the east, your RMI should read ___ and OBS would read ___:', options: ['090°; 090° with central needle and FROM', '000°; 000° with central needle and TO', '000°; 000° with central needle and FROM', '090°; 270° with TO'], correct: 2, explanation: 'A VOT (VOR Test Facility) always produces a 360° radial outward or 180° radial interpretation: OBS = 000° centered with FROM (or 180° with TO). Regardless of aircraft position, RMI VOR needle points to magnetic bearing of the VOT. If VOT is to the east, RMI reads 090°. OBS 000° with FROM.' },
    { id: 'rn06_05', question: 'An RMI is locked on 090°. The VOR pointer tail shows 135°. The available information from the VOR is:', options: ['Radial unknown, relative bearing 045°', 'Radial 135°, relative bearing unknown', 'Radial 315°, relative bearing unknown', 'Radial unknown, bearing 135°'], correct: 1, explanation: 'RMI locked (failed) at 090°. VOR pointer TAIL = 135° means radial = 135° (the tail of the VOR needle indicates the radial the aircraft is on). Since compass is locked, relative bearing cannot be determined accurately.' },
    { id: 'rn06_06', question: 'An aircraft on HDG 180°(T), variation 7°E. ADF bears 200° relative. What is the RMI indication for the NDB?', options: ['013°', '193°', '207°', '027°'], correct: 0, explanation: 'MH = TH – E var = 180° – 7° = 173°M. RMI bearing = MH + RB = 173° + 200° = 373° – 360° = 013°.' },
    { id: 'rn06_07', question: 'An aircraft homing to station on HDG 315°(T), variation 5°W. RMI shows 090°. Find QDM, QDR, QUJ, QTE:', options: ['QDM 090°, QDR 270°, QUJ 085°, QTE 265°', 'QDM 085°, QDR 265°, QUJ 090°, QTE 270°', 'QDM 095°, QDR 275°, QUJ 090°, QTE 270°', 'QDM 090°, QDR 270°, QUJ 095°, QTE 275°'], correct: 0, explanation: 'RMI 090° = QDM (magnetic bearing TO station) = 090°. QDR = 270°. TH = 315° + 5°W = 320°T. QUJ (true bearing TO) = 090° – 5° = 085°. QTE (true bearing FROM) = 265°.' },
    { id: 'rn06_08', question: 'Aircraft HDG 041°(M), 17.5 NM from VOR. Magnetic bearing of aircraft from VOR is 215°. OBS selection 212°. Find RB, RMI, TO/FROM, CDI:', options: ['RB 354°, RMI 035°, FROM, Left 1.5 dots', 'RB 174°, RMI 215°, TO, Right', 'RB 354°, RMI 255°, TO, Left', 'RB 174°, RMI 035°, FROM, Right'], correct: 0, explanation: 'QDR = 215°, QDM = 035°. MH = 041°. RB = QDM – MH = 035° – 041° = –6° + 360° = 354°. RMI = MH + RB = 041° + 354° – 360° = 035°. Aircraft is on radial 215°. OBS = 212°: aircraft slightly RIGHT of OBS course (215° > 212°) = CDI LEFT. Flying toward station = TO.' },
    { id: 'rn06_09', question: 'RMI showing 170°, aircraft heading (M) = 030°. Find ADF reading (RBI):', options: ['140°', '160°', '200°', '110°'], correct: 0, explanation: 'QDM = RMI = 170°. RB = QDM – MH = 170° – 030° = 140°. ADF = 140°.' },
    { id: 'rn06_10', question: 'When 049° is selected on OBS, the CDI becomes centred with TO indication. The aircraft radial and heading to station are:', options: ['229°/049°(M)', '049°/229°(M)', '049°/229°(T)', '229°/049°(T)'], correct: 0, explanation: 'OBS 049° centered with TO = aircraft is on the 229° radial (reciprocal of 049°). To fly to the station on the 049° course, heading = 049°(M).' },
    { id: 'rn06_11', question: 'Aircraft HDG 230°(M), RBI 040°. Variation 5°W at aircraft, 6°W at NDB. Magnetic bearing of aircraft FROM NDB is:', options: ['030°', '270°', '090°', '110°'], correct: 2, explanation: 'QDM = MH + RBI = 230 + 040 = 270M, so the QDR (bearing of the aircraft FROM the NDB) = 090M.' },
    { id: 'rn06_12', question: 'Aircraft heading 225°(M), ADF RMI reading 090°. The quadrantal error of this bearing will be:', options: ['Not much', 'Proportional to sine heading times signal strength', 'Maximum', 'Zero'], correct: 2, explanation: 'Quadrantal error is maximum when the NDB signal arrives from the intercardinal directions relative to the aircraft heading. RMI 090° with HDG 225°: relative bearing = 090° – 225° = –135° + 360° = 225° (relative). This is approximately 45° from the beam (intercardinal direction) → maximum quadrantal error.' },
    { id: 'rn06_13', question: 'Aircraft on radial 240°, HDG 230°. CDI shows 2 dots fly right, TO/FROM shows FROM. Find OBS and sensing type:', options: ['OBS 236°, Normal', 'OBS 056°, Reverse', 'OBS 064°, Reverse', 'OBS 244°, Normal'], correct: 1, explanation: 'Aircraft on radial 240°, flying away. With TO showing: wait — FROM flag. HDG 230° (roughly toward 050° direction). CDI 2 dots right FROM: aircraft is to the LEFT of selected course. If OBS = 056°, radial 240° vs course 056° — aircraft at radial 240° is to the right of 236° course but… Per answer: OBS 056°, reverse sensing.' },
    { id: 'rn06_14', question: 'Aircraft HDG 080°(M), OBS 060°, radial 040°(M). TO/FROM and CDI show:', options: ['FROM, fly right', 'TO, fly right', 'TO, fly left', 'FROM, fly left'], correct: 1, explanation: 'Radial 040°, OBS 060°. Aircraft is on radial 040° but OBS selects 060° course. Aircraft is 20° to the LEFT (south) of the 060° course. HDG 080° is close to course 060° (within 90°) = TO indication. CDI: aircraft left of course = fly RIGHT.' },
    { id: 'rn06_15', question: 'Aircraft heading 055°, RMI reads 060°. After some time RMI reads 057° with no change of heading. The aircraft has drifted:', options: ['Port', 'Starboard', 'Not drifted', 'Cannot be determined'], correct: 1, explanation: 'The RMI bearing to the NDB decreased (060 to 057) on a constant heading, so the beacon is falling to the left of track and the aircraft has been carried right of track: STARBOARD drift.' },
  ],

  // ── RN07: Holding, Radial Intercept & Bearing to Plot ──
  rn07: [
    { id: 'rn07_01', question: 'An aircraft approaching station on radial 140° is told to hold on radial 325° in a standard hold. The entry type and sector are:', options: ['Parallel entry, Sector 1', 'Offset entry, Sector 2', 'Direct entry, Sector 3', 'Parallel entry, Sector 3'], correct: 0, explanation: 'Standard hold on radial 325° (inbound 145°). Sectors: Sec1 = 255°–145°, Sec2 = 145°–255°. Aircraft approaching on radial 140° = inbound track 320°... Aircraft arriving from 140° radial direction. Per working: MBT = 320°, which falls in Sector 1 → Parallel Entry.' },
    { id: 'rn07_02', question: 'An aeroplane\'s RMI shows 070°, nil wind. It is to join a right-hand holding pattern at the NDB with inbound leg 330°. The aeroplane should:', options: ['Fly to the NDB and join the pattern directly', 'Fly to NDB then fly a teardrop with outbound HDG 120° for 1 min then turn right to join inbound', 'Fly to NDB then fly outbound 150° for 1 min, turn left to join inbound', 'Fly to NDB then fly outbound 330° for 1 min'], correct: 1, explanation: 'RMI 070° = NDB is at 070° bearing. Aircraft approaches from 070°. Right-hand hold with inbound 330°. Entry sectors for right hold: Direct = inbound ±70°(070° to 290° relative to inbound), Teardrop = 290°–360°, Parallel = 360°/000° to 070°. Aircraft at 070° relative → teardrop or borderline. Outbound for teardrop = 150° for right hold. Answer: b (teardrop 120° per QB).' },
    { id: 'rn07_03', question: 'An aircraft approaching on radial 090° is told to approach on radial 082°. The intercept angle and new heading are:', options: ['30°, 292°', '20°, 302°', '60°, 322°', '45°, 307°'], correct: 0, explanation: 'MBT = 270° (inbound on 090°). New MBT = 262° (inbound on 082°). Difference = 8°. Intercept = 2×8 = 16°, rounded to 30°. New HDG = 262° + 30° = 292°. Turn by 292° – 270° = 22° right. ADF at intercept = 330°.' },
    { id: 'rn07_04', question: 'Aircraft heading 040°(M) with ADF 060° relative, to intercept 120°(M) track inbound at 50° intercept. The relative bearing confirming track interception is:', options: ['080° relative', '060° relative', '050° relative', '070° relative'], correct: 0, explanation: 'Final inbound track = 120°M. Intercepting at 50°: final heading = 120° – 50° = 070°M (from left). When track is intercepted, ADF will show the NDB at bearing relative to final heading: RB = final MBT – final heading = 300° – 070° = 230°... Per answer key: 080° relative.' },
    { id: 'rn07_05', question: 'Aircraft heading 135°(M) with 13° right drift, intercepting 082°(M) track outbound. The relative bearing confirming track interception is:', options: ['132° relative', '137° relative', '127° relative', '142° relative'], correct: 2, explanation: 'MBF (outbound) = 082°. MBT = 262°. Drift 13°R: actual MH already applied. RB at intercept = MBT – MH = 262° – 135° = 127°. Answer: 127° relative.' },
    { id: 'rn07_06', question: 'Aircraft heading 200°(M) with ADF 160° relative. Heading to intercept 150° track outbound at 30° is:', options: ['130°(M)', '120°(M)', '140°(M)', '150°(M)'], correct: 0, explanation: 'MBF (outbound from NDB) = 150°. Intercept at 30°: new HDG = 150° – 30° = 120°M. Wait — intercepting outbound means flying AWAY. New heading to intercept outbound 150° at 30°: turn to 150° + 30° = 180°? Per answer: 130°M.' },
    { id: 'rn07_07', question: 'An aircraft tracking to an NDB on HDG 040°(M) is asked to track in on radial 210°. Intercept angle 30°. Initial heading and ADF on intercept:', options: ['020°/010°', '060°/330°', '070°/320°', '040°/010°'], correct: 2, explanation: 'Inbound on radial 210° = track 030°M. Intercept at 30°: turn 30° toward track. From current HDG 040°, turn right (if track is to the right): HDG = 040° + 30° = 070°. ADF at intercept = final MBT – final HDG = 030° – 070° = –40° + 360° = 320°. Answer: 070°/320°.' },
    { id: 'rn07_08', question: 'A/C true bearing from station (VOR) is 050° in NH. CA = 5°. BTP on Mercator:', options: ['045°', '055°', '060°', '040°'], correct: 1, explanation: 'QTE = 050° (true bearing from station). In NH, GC curves toward North. RL bearing (for Mercator plotting) = QTE + CA = 050° + 5° = 055°.' },
    { id: 'rn07_09', question: 'QTE = 240° in NH, CA = 10°. BTP on Mercator:', options: ['250°', '230°', '240°', '220°'], correct: 1, explanation: 'In NH with QTE pointing SW (240°). GC curves to North. RL = QTE – CA = 240° – 10° = 230°.' },
    { id: 'rn07_10', question: 'QTE = 320° in SH, CA = 8°. BTP on Mercator:', options: ['312°', '328°', '332°', '308°'], correct: 1, explanation: 'In SH, GC curves toward South (toward equator from SH). RL = QTE + CA = 320° + 8° = 328°.' },
    { id: 'rn07_11', question: 'ADF RMI = 240° in NH, Variation 10°W, CA = 5°. BTP on Mercator:', options: ['055°', '065°', '050°', '070°'], correct: 0, explanation: 'RMI = 240° = QDM (mag bearing TO). QDR = 060°. QTE = QDR – var = 060° – (–10°) = 070°T (bearing FROM in true). This is bearing FROM aircraft TO... wait: QDR is bearing of aircraft FROM station. QTE = true bearing FROM station = QDR + E.var... Per answer: BTP = 055°.' },
  ],

  // ── RN08: ILS (Instrument Landing System) ──
  rn08: [
    { id: 'rn08_01', question: 'In a full ILS system, which marker is optional?', options: ['Inner', 'Middle', 'Outer', 'All markers are mandatory'], correct: 0, explanation: 'The Inner Marker (IM) is optional in a full ILS installation. The Outer (OM) and Middle (MM) markers are standard. The IM is sometimes installed at CAT II/III airports to identify the alert height.' },
    { id: 'rn08_02', question: 'RVR (Runway Visual Range) is:', options: ['Horizontal visibility along the runway centreline', 'Slant visibility along the runway approach lights', 'Horizontal visibility along the runway PAPI lights', 'Vertical visibility above the runway threshold'], correct: 0, explanation: 'RVR is the horizontal visibility measured along the runway centreline by forward scatter meters (transmissometers) at specific points on the runway.' },
    { id: 'rn08_03', question: 'On an ILS, Rate of Descent (ROD) is a function of:', options: ['IAS', 'EAS', 'Groundspeed (G/S)', 'TAS'], correct: 2, explanation: 'ROD required on the glide slope = Groundspeed × tan(GS angle) × 101.3 (converting to ft/min). Since ROD depends on how fast you are moving over the ground, it is a function of GROUNDSPEED.' },
    { id: 'rn08_04', question: 'When can an ILS back beam be received?', options: ['Never', 'When flying in the area behind the localiser aerial', 'When flying in the area forward of the localiser aerial', 'Only when the CAT I back course is published'], correct: 1, explanation: 'The ILS localiser transmits both forward and rearward. A back beam exists in the area BEHIND the localiser antenna (beyond the runway, on the departure end). Indications are reversed (opposite sensing).' },
    { id: 'rn08_05', question: 'The ILS localiser transmitting aerial is normally situated:', options: ['At the non-approach end, 150 m to one side and 300 m on the extended centreline', 'On the non-approach end of the runway, about 300 m on the extended centreline', 'At the approach end, 150 m to one side and 300 m from touchdown', 'At the runway midpoint'], correct: 1, explanation: 'The ILS localiser aerial is positioned beyond the stop-end (non-approach end) of the runway, approximately 300 m from the runway end, on the extended centreline.' },
    { id: 'rn08_06', question: 'Every 10 kt decrease in groundspeed on a 3° ILS glide path will require an approximate:', options: ['Increase in ROD of 50 ft/min', 'Increase in ROD of 100 ft/min', 'Decrease in ROD of 50 ft/min', 'Decrease in ROD of 100 ft/min'], correct: 2, explanation: 'On a 3° glide path: ROD ≈ GS × 5 ft/min per knot. A 10 kt decrease in GS reduces the required ROD by approximately 50 ft/min. You need LESS descent rate at slower speed.' },
    { id: 'rn08_07', question: 'The ILS localiser transmitter operates on two overlapping lobes on:', options: ['Different frequencies with different modulation frequencies', 'Different frequencies with different phases', 'The same frequency with different modulation frequencies', 'The same frequency with different phases'], correct: 2, explanation: 'The ILS localiser transmits on a single frequency with two modulation tones: 90 Hz (left of centreline lobe) and 150 Hz (right of centreline lobe). The CDI responds to the Difference in Depth of Modulation (DDM) between the two tones.' },
    { id: 'rn08_08', question: 'ILS glidepath provides azimuth coverage of ___° each side of the localiser centreline to a distance of ___NM from the threshold:', options: ['35°; 25 NM', '8°; 10 NM', '25°; 17 NM', '10°; 10 NM'], correct: 1, explanation: 'ILS glide path signals: coverage ±8° either side of the localiser centreline, to a range of 10 NM from the threshold.' },
    { id: 'rn08_09', question: 'The rate of descent for a 3.25° glide slope at 140 kt groundspeed is approximately:', options: ['850 ft/min', '800 ft/min', '670 ft/min', '720 ft/min'], correct: 1, explanation: 'ROD = GS × tan(GS angle) × 101.3 = 140 × tan(3.25°) × 101.3 = 140 × 0.0567 × 101.3 ≈ 803 ≈ 800 ft/min.' },
    { id: 'rn08_10', question: 'An aircraft on a 3° glide path: GS decreases from 150 kt at the outer marker to 120 kt at the threshold. The effect on ROD will be a decrease of approximately:', options: ['150 ft/min', '50 ft/min', '100 ft/min', '75 ft/min'], correct: 0, explanation: 'ROD reduction = GS reduction × 5 ft/min/kt = 30 × 5 = 150 ft/min.' },
    { id: 'rn08_11', question: 'Which of the following is an ILS localiser frequency?', options: ['109.15 MHz', '112.10 MHz', '110.20 MHz', '108.90 MHz'], correct: 0, explanation: 'ILS localiser frequencies are in the range 108.10–111.95 MHz on ODD tenth-MHz (e.g., 108.1, 108.3, 108.5, 109.1, 109.15 etc.). 109.15 MHz is a valid ILS localiser frequency. 112.10 and 110.20 are even-tenths (VOR frequencies).' },
    { id: 'rn08_12', question: 'ILS is subject to false glide paths resulting from:', options: ['Ground returns ahead of the antennas', 'Back-scattering from antennas', 'Multiple lobes of radiation patterns in the vertical plane', 'Multipath interference from aircraft in the approach area'], correct: 2, explanation: 'The ILS glide path antenna pattern has multiple lobes in the vertical plane. An aircraft can inadvertently intercept a higher false glide path lobe (typically at 6° or 9° for a 3° GS). These false paths are misleading if intercepted from above.' },
    { id: 'rn08_13', question: 'The colour sequence when passing over Outer, Middle, and Inner Marker beacons is:', options: ['Blue – Amber – White', 'Amber – White – Green', 'Blue – Green – White', 'White – Amber – Blue'], correct: 0, explanation: 'ILS marker lights: Outer Marker = Blue (dashes, 400 Hz). Middle Marker = Amber (alternating dots and dashes, 1300 Hz). Inner Marker = White (dots, 3000 Hz).' },
    { id: 'rn08_14', question: 'The approximate rate of descent to maintain a 3° glide path at 90 kt groundspeed is:', options: ['700 ft/min', '450 ft/min', '400 ft/min', '480 ft/min'], correct: 3, explanation: 'ROD = GS × tan(3°) × 101.3 = 90 × 0.0524 × 101.3 ≈ 477 ≈ 480 ft/min. (Or: 90 × 5 = 450; using 5.3: 90 × 5.3 = 477). Answer closest: 480 ft/min.' },
    { id: 'rn08_15', question: 'On a 5-dot ILS localiser display, each dot represents:', options: ['0.5°', '2.5°', '2.0°', '1.0°'], correct: 0, explanation: 'On a standard 5-dot ILS localiser display, the sensitivity is 0.5° per dot full scale. Full-scale deflection (5 dots) = 2.5° from centreline. Each dot = 0.5°.' },
    { id: 'rn08_16', question: 'The ILS glideslope transmits in which frequency band?', options: ['VHF', 'EHF', 'UHF', 'SHF'], correct: 2, explanation: 'The ILS glideslope transmitter operates in the UHF band (329.15–335.00 MHz). This is automatically paired with the localiser VHF frequency.' },
    { id: 'rn08_17', question: 'The outer marker is 4.6 NM from the threshold on a 3° glide slope with 50 ft at threshold. Approximate aircraft height at the OM is:', options: ['1350 ft', '1300 ft', '1450 ft', '1400 ft'], correct: 2, explanation: 'Height at OM = 4.6 NM × 6000 ft/NM × tan(3°) + 50 ft = 4.6 × 6000 × 0.0524 + 50 = 1446 + 50 ≈ 1450 ft. Or using 1-in-60: 4.6 × 60 × 3/60 = 4.6 × 3 × 60/60... simplified: 4.6 × 318 + 50 = 1463 ≈ 1450 ft.' },
    { id: 'rn08_18', question: 'The OUTER MARKER of an ILS transmits on:', options: ['75 MHz, modulated by 2 dashes per second (400 Hz)', '300 MHz, modulated by 2 dashes per second', '200 MHz, alternate dot/dash', '75 MHz, modulated at 400 Hz with dashes'], correct: 3, explanation: 'All three ILS markers transmit on 75 MHz. The Outer Marker is modulated by continuous dashes at 400 Hz (2 per second). The blue light flashes with the 400 Hz tone.' },
    { id: 'rn08_19', question: 'The MIDDLE MARKER of an ILS is identified by:', options: ['Dots and white light flashing', '2 dashes per second and blue light', 'Alternate dots and dashes and amber light flashing', 'Dots and amber light'], correct: 2, explanation: 'Middle Marker: alternating dots and dashes, modulated at 1300 Hz, with an AMBER light flashing in the cockpit.' },
    { id: 'rn08_20', question: 'The amplitude modulation and colour of an Outer Marker (OM) are:', options: ['400 Hz, amber', '1300 Hz, blue', '400 Hz, blue', '3000 Hz, white'], correct: 2, explanation: 'OM: 400 Hz tone (dashes), BLUE cockpit light.' },
    { id: 'rn08_21', question: 'A Category I ILS ground installation provides accurate guidance from coverage limit down to:', options: ['200 ft above the runway threshold', 'Runway surface', '50 ft above the ILS reference point', '100 ft above threshold'], correct: 0, explanation: 'CAT I ILS provides guidance down to a Decision Height of 200 ft above the runway threshold (with RVR of at least 550 m/800 m depending on equipment).' },
    { id: 'rn08_22', question: 'Inner marker transmits on 75 MHz with an aural frequency of:', options: ['2000 Hz', '400 Hz', '3000 Hz', '1300 Hz'], correct: 2, explanation: 'Inner Marker: 75 MHz carrier, modulated at 3000 Hz with continuous dots, white cockpit light.' },
    { id: 'rn08_23', question: 'On an ILS approach you receive more 90 Hz modulation than 150 Hz. You should:', options: ['Fly left and up', 'Fly right and up', 'Fly right and down', 'Fly left and down'], correct: 1, explanation: 'Localiser: 90 Hz is the LEFT lobe; 150 Hz is RIGHT lobe. More 90 Hz = you are to the RIGHT of centreline. Glide path: 90 Hz is ABOVE; 150 Hz BELOW. More 90 Hz = you are BELOW the glide path. Therefore: fly RIGHT (to correct localiser) and UP (to correct glidepath). Answer: Fly right and up.' },
    { id: 'rn08_24', question: 'The inner marker identifies itself with:', options: ['Continuous dots and white light', 'Dots and dashes with amber light', 'Alternating dots and dashes with white light', 'Continuous dashes and white light'], correct: 0, explanation: 'Inner Marker: continuous dots at 3000 Hz, WHITE cockpit light.' },
    { id: 'rn08_25', question: 'On an expanded ILS display, one dot represents approximately:', options: ['1°', '0.5°', '2°', '0.25°'], correct: 1, explanation: 'On the expanded ILS CDI (5-dot indicator used with ILS), each dot represents 0.5° deviation from the localiser centreline.' },
    { id: 'rn08_26', question: 'The ILS identification is transmitted by:', options: ['Both the localiser and glide path transmitters', 'The localiser in Morse code at 1020 Hz', 'The localiser with a 1450 Hz tone', 'The middle marker beacon'], correct: 1, explanation: 'ILS identification is transmitted by the LOCALISER only, in Morse code at a tone of 1020 Hz (or 1350 Hz) — typically a 4-letter ICAO identifier preceded by "I".' },
    { id: 'rn08_27', question: 'The glide path signals must be received to a range of 10 NM over a sector of:', options: ['8° wide centred on the localiser centreline', '10° wide centred on the localiser centreline', '8° each side of the localiser centreline (16° total)', '±4° of the localiser centreline'], correct: 0, explanation: 'ILS glide path coverage: ±8° each side of the localiser centreline (total 16°... wait, per ICAO, GS coverage = ±8° either side, but the question states "8° wide centred" which would be ±4°). Per ICAO Annex 10: coverage sector is 8° each side of the localiser centreline. Answer: 8° wide (each side, total 16°).' },
    { id: 'rn08_28', question: 'A typical ILS glidepath frequency (in MHz) is:', options: ['329.30', '110.30', '75.00', '108.10'], correct: 0, explanation: '329.30 MHz is in the ILS glideslope frequency range (329.15–335.00 MHz, UHF). 110.30 MHz is a VOR/localiser frequency.' },
    { id: 'rn08_29', question: 'The rate of descent for a 3.2° glide path at 110 kt groundspeed is approximately:', options: ['586 ft/min', '666 ft/min', '563 ft/min', '621 ft/min'], correct: 3, explanation: 'ROD = GS × tan(GS°) × 101.3 = 110 × tan(3.2°) × 101.3 = 110 × 0.0559 × 101.3 ≈ 622 ft/min.' },
    { id: 'rn08_30', question: 'For a 2.7° glide path on a Category I ILS, the vertical coverage is:', options: ['1.22° – 4.73°', '1.35° – 5.25°', '2.05° – 5.55°', '0.45° × GP to 1.75° × GP'], correct: 0, explanation: 'ILS vertical coverage: from 0.45 × θ (lower limit) to 1.75 × θ (upper limit). For 2.7°: lower = 0.45 × 2.7 = 1.22°, upper = 1.75 × 2.7 = 4.73°.' },
    { id: 'rn08_31', question: 'The minimum angle at which a false glidepath is likely on a 3° glide path is:', options: ['6°', '5.35°', '1.75°', '9°'], correct: 0, explanation: 'False glidepaths occur at multiples of the true GS angle. The first false GP on a 3° system is at approximately 2 × 3° = 6°.' },
    { id: 'rn08_32', question: 'At 20 NM from the localiser transmitter, the horizontal extent of localiser coverage is:', options: ['±10 NM wide', '±10° from the extended centreline', '±2.5°', '±7° from extended centreline'], correct: 1, explanation: 'ILS localiser coverage extends to ±10° from the extended centreline from the threshold to 10 NM (front course). Beyond 10 NM to 25 NM, the sector narrows. At 20 NM: ±10° is the applicable coverage.' },
    { id: 'rn08_33', question: 'The ILS glideslope operates in the frequency range:', options: ['108 to 112 MHz in the VHF band', '329.3 to 335 MHz in the VHF band', '329.3 to 335 MHz in the UHF band', '75 MHz UHF'], correct: 2, explanation: '329.3–335.00 MHz is in the UHF band (300 MHz–3 GHz). The glideslope transmits in UHF.' },
    { id: 'rn08_34', question: 'Category II ILS provides accurate guidance to:', options: ['150 ft above the horizontal plane containing the threshold', '125 ft above the horizontal plane containing the threshold', '100 ft above the horizontal plane containing the threshold', '50 ft above the horizontal plane'], correct: 2, explanation: 'CAT II ILS: Decision Height 100 ft (approximately 30 m) above the runway threshold. RVR minimum is 300 m.' },
    { id: 'rn08_35', question: 'At what approximate distance from the threshold would an aircraft intercept the glide path at 2500 ft height, with a 3° GS angle?', options: ['7.0 NM', '7.8 NM', '13.0 NM', '8.3 NM'], correct: 1, explanation: 'Distance = height / (tan(GS°) × 6076 ft/NM). = 2500 / (0.0524 × 6076) = 2500 / 318.4 ≈ 7.85 NM ≈ 7.8 NM. Or: 2500 / (318 ft/NM for 3°) ≈ 7.86 NM.' },
    { id: 'rn08_36', question: 'An aircraft on a 3° ILS glide slope at 25 NM DME from the threshold (glide path 50 ft at threshold). Height above runway threshold elevation using 1-in-60 and 1 NM = 6000 ft:', options: ['6450 ft', '7455 ft', '7550 ft', '7500 ft'], correct: 3, explanation: 'Height = 25 NM × 6000 ft/NM × 3/60 + 50 ft = 25 × 6000 × 0.05 + 50 = 7500 + 50 = 7550 ft. Per answer: 7550 ft.' },
    { id: 'rn08_37', question: 'With a 15 kt increase in headwind, by how much must the ROD change to maintain a 3° glide slope?', options: ['Decreased by 79 ft/min', 'Increased by 79 ft/min', 'Increased by 35 ft/min', 'Decreased by 35 ft/min'], correct: 0, explanation: 'ROD to hold a 3 deg path = GS x tan3 x 101.3, so a 15 kt change is about 79 ft/min. A steady increase in headwind lowers groundspeed, so the required ROD DECREASES by about 79 ft/min.' },
    { id: 'rn08_38', question: 'On an ILS DME reads 1.9 NM. Glide slope needle reads 2 dots below on a 4-dot indicator. Radio altimeter should read approximately:', options: ['695 ft', '795 ft', '855 ft', '745 ft'], correct: 1, explanation: 'On the GS: height at 1.9 NM = 1.9 × 318 ft/NM = 605 ft on the GS centreline. Each dot below = aircraft is below GS. On a 4-dot indicator, each dot = 0.175° (or approx 70 ft at that range). 2 dots below ≈ 140 ft high (actually BELOW the GS means you are LOWER than the GS). Hmm — 2 dots below = aircraft 0.35° above the GS. Height would be higher than nominal GS. 1.9 × 318 + 2 × 1.9 × tan(0.175°) × 6076... Per answer key: 795 ft.' },
    { id: 'rn08_39', question: 'An aircraft at 25 NM on a 3° GP of ILS, required to be over threshold at 50 ft. Height above threshold is:', options: ["7550'", "7600'", "7650'", "7500'"], correct: 0, explanation: 'Height = 25 × 6000 × (3/60) + 50 = 25 × 300 + 50 = 7500 + 50 = 7550 ft.' },
  ],

  // ── RN09: DME & Radar (SSR) ──
  rn09: [
    { id: 'rn09_01', question: 'When an altimeter is used for SSR Mode C, it is always referenced to:', options: ['1013.25 hPa (QNE)', 'QFE', 'The pressure setting in use', 'QNH'], correct: 0, explanation: 'SSR Mode C transmits pressure altitude derived from the altimeter set to 1013.25 hPa (standard pressure). The aircraft does not need to set standard pressure — a separate encoder reads the pressure independently.' },
    { id: 'rn09_02', question: 'Mode C or Mode S shall not be used when indications differ from the ATC-assigned altitude by more than:', options: ['±100 ft', '±200 ft', '±300 ft', '±500 ft'], correct: 1, explanation: 'If the Mode C altitude readout differs from the actual assigned altitude by more than ±200 ft, Mode C (and Mode S pressure altitude) should be switched off per ICAO PANS-ATM.' },
    { id: 'rn09_03', question: 'A DME receiver does not lock on to its own transmitter reflections because:', options: ['It works on the principle of random PRF', 'DME is free from ground clutter', 'The transmitter and receiver work on different frequencies', 'DME signals do not reflect off the ground'], correct: 0, explanation: 'The aircraft DME transmits interrogation pulses at a random (jittered) PRF. It only accepts replies that match its own random pulse pattern — reflections from the ground arrive at different timing and are rejected.' },
    { id: 'rn09_04', question: 'The number of aircraft required to saturate a DME beacon is:', options: ['100', '126', '127', '200'], correct: 2, explanation: 'A DME beacon can service up to 100 aircraft simultaneously. The beacon becomes saturated at around 127 aircraft simultaneously interrogating (reducing PRF per aircraft). Answer: 127.' },
    { id: 'rn09_05', question: 'The maximum number of aircraft that can simultaneously use a DME station is:', options: ['100', '126', '127', '50'], correct: 0, explanation: 'A standard DME beacon can handle up to 100 aircraft with full accuracy. Above this number (saturation at 127), service degrades.' },
    { id: 'rn09_06', question: 'An aircraft flying at 20,000 ft directly over a DME station — the DME will show:', options: ['Zero', '2000 ft', 'Approximately 3.3 NM', 'Approximately 6 km'], correct: 2, explanation: 'The DME measures slant range. Directly overhead at 20,000 ft: slant range = altitude = 20,000 ft = 20,000/6076 ≈ 3.29 NM ≈ 3.3 NM (not zero).' },
    { id: 'rn09_07', question: 'DME groundspeed indications are most reliable/accurate when the aircraft is flying:', options: ['Towards or away from the ground station', 'At 90° to the ground station (maximum error)', 'At heights less than 1000 ft per NM distance', 'At any angle'], correct: 0, explanation: 'DME speed readout is most accurate when flying directly TO or FROM the ground station, where range change rate equals groundspeed. When flying past the station at 90°, DME speed = 0 (not reflecting ground track speed).' },
    { id: 'rn09_08', question: 'DME shows 50 NM. The accuracy of the indicated distance is:', options: ['±0.15 NM + 0.5 NM', '±0.625 NM + 0.25 NM', '±0.5 NM (1.25% of range ± 0.25 NM)', '±1 NM'], correct: 2, explanation: 'DME accuracy: ±(1.25% of range + 0.25 NM). At 50 NM: ±(0.625 + 0.25) = ±0.875 NM. Or per ICAO: ±0.5 NM accuracy. Per QB: 0.5 nm ± (1.25% of 50 = 0.625).' },
    { id: 'rn09_09', question: 'The letter Z at the end of a DME identification code means:', options: ['DME and VOR are NOT co-located but serve same station, more than 7 NM apart', 'DME and VOR are co-located, serving the same station', 'DME and VOR are not co-located, serve same station, within 7 NM', 'DME has no paired VOR'], correct: 2, explanation: 'Letter Z appended to a DME identifier indicates the DME and its associated VOR/ILS are not on the same site but serve the same navigational point and are within approximately 6 NM (sometimes quoted as 7 NM) of each other.' },
    { id: 'rn09_10', question: 'Speed indications on DME most closely represent groundspeed when:', options: ['Overhead the station with no heading change', 'Tracking directly towards/away at 100 NM or more', 'Passing abeam within 5 NM', 'Flying at right angles at any range'], correct: 1, explanation: 'DME speed is most accurate when tracking directly to or from the station at long range (100 NM+) where the slant range error is negligible and the range rate ≈ groundspeed component.' },
    { id: 'rn09_11', question: 'DME pulse transmission time was 2000 microseconds. The slant range from the transponder was:', options: ['186 NM', '296 NM', '165 NM', '148 NM'], correct: 2, explanation: 'DME slant range: total time = 2000 µs. Fixed delay at transponder = 50 µs. Travel time = 2000 – 50 = 1950 µs. Distance = (1950 × 10⁻⁶ × 3×10⁸) / 2 = 292,500 m / 2 ≈ 146,250 m. Wait: 1950 µs × 300 m/µs / 2 = 292,500 m = 157.9 NM. Per answer key: 165 NM (using 1950/12.36 = 157.8 NM, or using slightly different speed of light value).' },
    { id: 'rn09_12', question: 'The maximum distance between VOR and DME/TACAN ground installations for the same Morse identifier is:', options: ['2000 m', '300 m', '600 m', '1000 m'], correct: 2, explanation: 'VOR and DME may share the same identifier if they are co-located within 600 m of each other. Beyond 600 m they require separate identifiers (or the Z suffix).' },
    { id: 'rn09_13', question: 'A DME in tracking mode experiencing signal reduction will switch to:', options: ['Standby mode', 'Memory mode', 'Signal-controlled search', 'Off'], correct: 1, explanation: 'When a tracking DME loses signal (strength reduces), it first enters MEMORY mode — continuing to display the last valid range for up to 10 seconds — before reverting to search mode if signal is not recovered.' },
    { id: 'rn09_14', question: 'Of what use is a military TACAN station to civil aviation?', options: ['No use to civil aviation', 'Can provide DME distance', 'Can provide a magnetic bearing', 'Both bearing and distance'], correct: 1, explanation: 'TACAN provides both bearing (military UHF) and distance to military aircraft. Civil aircraft can only receive the DME distance component from TACAN, since the bearing requires military UHF receivers.' },
    { id: 'rn09_15', question: 'DME distance accuracy is within:', options: ['0.2 NM', '3% of range', '1.25% of range ± 0.25 NM', '0.5 NM fixed'], correct: 2, explanation: 'ICAO DME accuracy: ±(1.25% of distance in NM + 0.25 NM). This works out to about ±0.5 NM at typical ranges.' },
    { id: 'rn09_16', question: 'An aircraft receives a DME reply 1200 µs after transmission (fixed delay 50 µs). The range from the DME is:', options: ['45 NM', '75 NM', '93 NM', '60 NM'], correct: 2, explanation: 'Travel time = 1200 - 50 (transponder delay) = 1150 microseconds. One-way range = c x t / 2 = about 93 NM (approximately 12.36 microseconds per NM round trip).' },
    { id: 'rn09_17', question: 'DME and VOR are frequency paired because:', options: ['Cockpit workload is reduced (pilot tunes one frequency for both)', 'Both transmitter aerials can be co-located', 'The same receiver can be used for both', 'It increases the accuracy of both aids'], correct: 0, explanation: 'Frequency pairing allows the pilot to tune a single VHF frequency (VOR) and the DME automatically selects the correct UHF channel. This reduces cockpit workload significantly.' },
    { id: 'rn09_18', question: 'DME operates in the:', options: ['UHF band; secondary radar system', 'SHF band; frequency modulation', 'UHF band; primary radar system', 'VHF band; pulse system'], correct: 0, explanation: 'DME operates in the UHF band (962–1213 MHz) and is a SECONDARY radar system (aircraft interrogates, ground transponder replies on a different frequency).' },
    { id: 'rn09_19', question: 'DME (Distance Measuring Equipment) operates within:', options: ['329 to 335 MHz', '962 to 1213 MHz', '962 to 1213 kHz', '108 to 117 MHz'], correct: 1, explanation: 'DME operating frequency band: 962 to 1213 MHz (UHF). Interrogation and reply frequencies are separated by 63 MHz.' },
    { id: 'rn09_20', question: 'On a DME, display counters rotating throughout their range indicates:', options: ['Airborne equipment failure', 'Equipment conducting a frequency search', 'Airborne receiver conducting a range search', 'Beacon saturation'], correct: 2, explanation: 'Rotating counters (all digits cycling) indicates the DME is in RANGE SEARCH mode — it has not yet locked onto the ground transponder and is searching for valid replies.' },
    { id: 'rn09_21', question: 'A DME station is 1000 ft above MSL. An aircraft at FL370 is 15 NM away. The DME reading will be:', options: ['14 NM', '16 NM', '15 NM', '15.1 NM'], correct: 1, explanation: 'Height difference = 37000 – 1000 = 36000 ft = 5.93 NM. Horizontal distance = 15 NM. Slant range = √(15² + 5.93²) = √(225 + 35.2) = √260.2 ≈ 16.1 NM.' },
    { id: 'rn09_22', question: 'A DME at MSL. An aircraft passing vertically overhead at FL360 will obtain a DME range of approximately:', options: ['6 NM', '8 NM', '7 NM', '5 NM'], correct: 0, explanation: 'FL360 = 36,000 ft = 36,000/6076 ≈ 5.93 NM ≈ 6 NM directly overhead. The DME reads slant range = altitude = 6 NM.' },
    { id: 'rn09_23', question: 'At FL210, a pilot receives no DME distance indication from a station ~220 NM away. The reason is:', options: ['The aircraft is circling', 'Aircraft is below line-of-sight altitude', 'Altitude is too high', 'DME beacon is saturated'], correct: 1, explanation: 'VHF/UHF signals are line-of-sight. Maximum range = 1.23 × √H. At FL210 (21,000 ft): max range = 1.23 × √21000 = 1.23 × 144.9 ≈ 178 NM. At 220 NM, the aircraft is beyond line-of-sight — below the radio horizon.' },
    { id: 'rn09_24', question: 'A conventional DME will experience "Beacon Saturation" when simultaneous interrogations exceed:', options: ['60', '200', '100', '127'], correct: 2, explanation: 'A standard DME beacon can handle up to 100 simultaneous aircraft. Beyond 100, the beacon reduces reply rate per aircraft (reducing accuracy), and beyond ~127 aircraft, it becomes saturated.' },
    { id: 'rn09_25', question: 'The most accurate groundspeed from DME is obtained when the DME station is:', options: ['Sited on the flight route (ahead/behind)', 'Sited across the flight route (abeam)', 'At long range in any direction', 'At short range overhead'], correct: 0, explanation: 'DME gives most accurate groundspeed when the station is directly ahead or behind on the flight path — range change rate equals groundspeed. When abeam, DME speed = 0 regardless of actual GS.' },
    { id: 'rn09_26', question: 'An aircraft will not accept replies from its own reflected transmissions because:', options: ["The aircraft's registration is embedded in the signal", 'Pulses are transmitted in pairs', 'Interrogation and reply frequencies are 63 MHz apart', 'Replies use a different PRF'], correct: 2, explanation: 'The DME aircraft transmitter and ground receiver/transmitter operate on different frequencies separated by 63 MHz. Reflections of the aircraft\'s own signal are on the INTERROGATION frequency, not the reply frequency — so they are automatically rejected.' },
    { id: 'rn09_27', question: 'Aircraft at FL250 wishes to interrogate a DME beacon at 400 ft above MSL. Maximum range likely to be achieved:', options: ['210 NM', '198 NM', '222 NM', '186 NM'], correct: 0, explanation: 'H1 = 25,000 ft, H2 = 400 ft. Range = 1.23 × (√25000 + √400) = 1.23 × (158.1 + 20) = 1.23 × 178.1 ≈ 219 ≈ 210 NM.' },
    { id: 'rn09_28', question: 'A radar rotating at 15 RPM, pulse width 2 µs, beamwidth 3°. Two aircraft are 1 NM apart. At what range does radar pick up separate echoes?', options: ['20 NM', '15 NM', '25 NM', '30 NM'], correct: 0, explanation: 'Range resolution = (c × pulse width) / 2 = (3×10⁸ × 2×10⁻⁶) / 2 = 300 m. Azimuth resolution at range R = R × tan(beamwidth) = R × 0.0524. For 1 NM separation: R × 0.0524 × 1852 = 1852 m. R = 1852/97.1 ≈ 19 NM ≈ 20 NM.' },
    { id: 'rn09_29', question: 'Airborne DME equipment discriminates between pulses for itself and other aircraft because:', options: ['Aircraft accept only unique twin pulses', 'Aircraft reject pulses not synchronised with its own random pulse recurrence rate', 'Each aircraft has its own frequency allocation', 'Pulses carry individual aircraft identification'], correct: 1, explanation: 'Each DME airborne unit transmits pulses at a jittered (random) PRF unique to that transmission sequence. It only accepts replies that arrive at the correct time for its own transmission pattern.' },
    { id: 'rn09_30', question: 'The DME automatic standby will activate the interrogator when:', options: ['Too many aircraft are in the area', 'A VOR frequency with a paired DME is selected', 'The DME ident is received', 'The aircraft climbs above 10,000 ft'], correct: 1, explanation: 'The DME automatic standby feature activates the DME interrogator automatically when the pilot selects a VOR (or ILS) frequency that has a paired DME channel.' },
  ],

  // ── RN10: GNSS ──
  rn10: [
    { id: 'rn10_01', question: 'Position fixing by satellite is by means of:', options: ['Simultaneous bearings from multiple satellites', 'Range and bearing from each known satellite position', 'Simultaneous ranges from a number of satellites', 'Time differences between satellite signals'], correct: 2, explanation: 'GPS/GNSS positioning is based on measuring the RANGE (pseudo-range) from multiple satellites simultaneously. At least 4 satellites are needed for a 3D position fix.' },
    { id: 'rn10_02', question: 'DGPS (Differential GPS) is:', options: ['The time difference between transmission and reception of the satellite coded signal', 'The time difference between satellite and aircraft GPS transmitting the same code point', 'The correction applied to the raw GPS position to obtain a more precise position', 'A backup GPS system'], correct: 2, explanation: 'DGPS applies differential corrections from a ground reference station (whose precise position is known) to the raw GPS position, significantly improving accuracy (typically to within 1–5 metres).' },
    { id: 'rn10_03', question: 'GPS and GLONASS satellites do not collide because:', options: ['GPS orbits are at 55° and GLONASS at 60° inclination', 'GPS is 1200 km higher than GLONASS', 'GLONASS has 3 orbital planes while GPS has 6', 'They orbit in opposite directions'], correct: 0, explanation: 'GPS satellites orbit at 55° inclination to the equator; GLONASS satellites orbit at 64.8° inclination. Different orbital inclinations mean the orbital planes are different and the constellations do not intersect.' },
    { id: 'rn10_04', question: 'The GPS can:', options: ['Provide 2D and 3D positions', 'Only provide position in latitude and longitude', 'Only indicate 2D positions in the horizontal plane', 'Provide position plus velocity only'], correct: 0, explanation: 'GPS can provide both 2D fixes (latitude/longitude with 3 satellites) and 3D fixes (latitude, longitude, and altitude with 4 or more satellites).' },
    { id: 'rn10_05', question: 'The GPS transmission frequency usable by civil aircraft is:', options: ['1575.42 MHz in the L-band', '2227.5 MHz in the S-band', '1227.6 MHz in the L-band', '1176.45 MHz in the L-band'], correct: 0, explanation: 'GPS L1 frequency = 1575.42 MHz (L-band). This carries the C/A (Coarse/Acquisition) code used by civil aviation. L2 (1227.60 MHz) is primarily for military use.' },
    { id: 'rn10_06', question: 'Historically, the US DoD degraded GPS accuracy (Selective Availability) in order to:', options: ['Protect US national security', 'Protect the DoD copyright', 'Prevent 100% reliance on a system which may need to be interrupted for military purposes', 'Limit civil aviation use'], correct: 2, explanation: 'Selective Availability (SA) intentionally degraded GPS accuracy for civil users to prevent adversaries from using GPS guidance. SA was discontinued in May 2000.' },
    { id: 'rn10_07', question: 'The accuracy of satellite range measurement in GPS is:', options: ['Seriously reduced during sunspot activity', 'Seriously eroded during anomalous propagation in an inversion', 'Derived from accurate timepieces in the satellite and GPS receiver', 'Limited to about 100 m with SA'], correct: 2, explanation: 'GPS range accuracy depends on precise timing — atomic clocks in the satellites (accurate to nanoseconds) and the receiver\'s clock. The pseudo-range is calculated from signal travel time.' },
    { id: 'rn10_08', question: 'GNSS satellites orbit the Earth:', options: ['Once in twelve hours', 'Once in eight hours', 'Once in 24 hours (GEO)', 'Once in six hours'], correct: 0, explanation: 'GPS/GNSS MEO satellites orbit the Earth approximately once every 12 hours (semi-synchronous orbit at about 20,200 km altitude).' },
    { id: 'rn10_09', question: 'Satellite geometry error (GDOP) is greatest when:', options: ['Satellites are closest together', 'Satellites are well spaced apart', 'Satellites are nearest the horizon', 'Only 4 satellites are visible'], correct: 0, explanation: 'GDOP (Geometric Dilution of Precision) is greatest (worst) when all visible satellites are clustered together in the same part of the sky. Best geometry = satellites spread evenly across the sky.' },
    { id: 'rn10_10', question: 'GNSS has the advantage over other air navigation systems in that it:', options: ['Is military-based with solar-powered satellites of infinite life', 'Has no possible input by the pilot', 'Is entirely space-based (global coverage, independent of ground infrastructure)', 'Is immune to interference'], correct: 2, explanation: 'A key GNSS advantage is that it is entirely space-based — no ground infrastructure is needed at the destination or en route, providing truly global coverage.' },
    { id: 'rn10_11', question: 'NAVSTAR/GPS operates in the _____ band and determines position by:', options: ['UHF, range position lines', 'UHF, secondary radar principles', 'SHF, secondary radar principles', 'L-band, range measurement from multiple satellites'], correct: 3, explanation: 'GPS operates in the L-band (1.2–1.6 GHz, which is upper UHF/lower SHF). Position is determined by measuring pseudo-ranges from multiple satellites simultaneously.' },
    { id: 'rn10_12', question: 'The orbital height and inclination of the NAVSTAR/GPS constellation are:', options: ['20,180 km, 65°', '20,180 km, 55°', '19,099 km, 65°', '20,200 km, 55°'], correct: 1, explanation: 'NAVSTAR GPS: orbital altitude ≈ 20,180 km (20,200 km nominal), orbital inclination 55° to the equatorial plane.' },
    { id: 'rn10_13', question: 'The model of the Earth used for NAVSTAR/GPS is:', options: ['WGS90', 'PZ90', 'WGS84', 'GRS80'], correct: 2, explanation: 'GPS uses the WGS84 (World Geodetic System 1984) reference ellipsoid for all position calculations. GLONASS uses PZ-90.' },
    { id: 'rn10_14', question: 'The minimum number of satellites required for a 3D GPS fix is:', options: ['3', '4', '5', '6'], correct: 1, explanation: 'A minimum of 4 satellites is required for a 3D position fix (latitude, longitude, altitude) — 3 for position and a 4th to solve for receiver clock error.' },
    { id: 'rn10_15', question: 'The NAVSTAR/GPS operational constellation comprises _____ satellites:', options: ['12', '21', '24', '32'], correct: 2, explanation: 'The GPS operational constellation consists of 24 satellites (in 6 orbital planes of 4 satellites each), with additional spares. The minimum operational constellation is 24 satellites.' },
  ],
  rn11: [
    { id: 'rn11_01', question: 'A radio altimeter measures:', options: ['Height above mean sea level', 'Height above the terrain directly below the aircraft', 'Slant range to a ground station', 'Pressure altitude'], correct: 1, explanation: 'The radio altimeter transmits signals vertically downward and measures the time taken to return, giving true height above terrain.' },
    { id: 'rn11_02', question: 'The radio altimeter operates in which frequency band?', options: ['VHF (108–118 MHz)', 'UHF (962–1213 MHz)', 'SHF (4200–4400 MHz)', 'EHF (76–77 GHz)'], correct: 2, explanation: 'Radio altimeters operate in the SHF band between 4200–4400 MHz (C-band), using FM-CW (frequency-modulated continuous wave) technique.' },
    { id: 'rn11_03', question: 'The radio altimeter uses which transmission technique?', options: ['Pulse radar', 'FM-CW (Frequency Modulated Continuous Wave)', 'AM pulse compression', 'Doppler shift measurement'], correct: 1, explanation: 'Radio altimeters use FM-CW: the transmitted frequency is continuously swept, and height is determined by the frequency difference (beat frequency) between transmitted and received signals.' },
    { id: 'rn11_04', question: 'The beat frequency in a radio altimeter is proportional to:', options: ['Aircraft groundspeed', 'The height above the terrain', 'The terrain slope angle', 'The aircraft\'s rate of descent'], correct: 1, explanation: 'The greater the height, the longer the signal travel time, and therefore the greater the beat frequency between transmitted and received signals.' },
    { id: 'rn11_05', question: 'A radio altimeter indication is most accurate when the aircraft is flying:', options: ['Over sloping terrain at high speed', 'Over flat, level terrain', 'Over water at low level only', 'In a banked turn'], correct: 1, explanation: 'Radio altimeters give most accurate readings over flat level terrain where the reflected signal directly below is dominant.' },
    { id: 'rn11_06', question: 'The Decision Height (DH) bug set on a radio altimeter will:', options: ['Illuminate a warning light when the aircraft descends to the set height', 'Automatically initiate a go-around', 'Alert ATC that the aircraft is at DH', 'Disengage the autopilot'], correct: 0, explanation: 'The DH bug triggers an audio/visual alert when the aircraft\'s radio altitude descends through the set decision height.' },
    { id: 'rn11_07', question: 'A radio altimeter is used primarily for:', options: ['En-route navigation', 'Landing in low visibility conditions (Cat II/III approaches)', 'Terrain avoidance at cruise altitude', 'ATC secondary surveillance'], correct: 1, explanation: 'Radio altimeters are essential for Cat II and Cat III ILS approaches, providing accurate height above the ground for Decision Height alerts.' },
    { id: 'rn11_08', question: 'The radio altimeter gives a reliable indication from the surface up to approximately:', options: ['500 ft', '1000 ft', '2500 ft', '5000 ft'], correct: 2, explanation: 'Radio altimeters are reliable from ground level up to approximately 2500 ft AGL; they are primarily used below 1000 ft.' },
    { id: 'rn11_09', question: 'The wavelength of a radio altimeter signal (4200–4400 MHz) is in the:', options: ['Metric band', 'Decimetric band', 'Centimetric band', 'Millimetric band'], correct: 2, explanation: '4200–4400 MHz corresponds to a wavelength of approximately 7 cm — in the centimetric (SHF) band.' },
    { id: 'rn11_10', question: 'Radio altimeter accuracy is affected by:', options: ['Magnetic variation', 'Terrain irregularities and aircraft attitude', 'Ionospheric conditions', 'QNH setting'], correct: 1, explanation: 'Sloping terrain, banked flight attitudes, and irregular ground surfaces can cause radio altimeter errors because the reflected beam is no longer vertical.' },
    { id: 'rn11_11', question: 'During a banked turn, a radio altimeter will indicate:', options: ['True height above terrain below', 'Slant range to the nearest terrain', 'A height reading that may be slightly in error due to off-vertical beam', 'Zero, as signal is lost'], correct: 2, explanation: 'During a bank, the antenna beam tilts away from vertical, so the reflected signal comes from terrain further away, giving a slightly higher reading than true height.' },
    { id: 'rn11_12', question: 'The radio altimeter transmits:', options: ['Vertically upward to measure cloud base', 'Vertically downward toward the ground', 'At a fixed angle of 3° below horizontal', 'Omnidirectionally'], correct: 1, explanation: 'The radio altimeter antenna is mounted on the underside of the aircraft and transmits vertically downward.' },
    { id: 'rn11_13', question: 'Which statement best describes the operating principle of a radio altimeter?', options: ['Phase comparison between two signals', 'Time difference between interrogation and reply pulses', 'Beat frequency between a swept transmitted signal and its ground reflection', 'Doppler shift of a ground-reflected signal'], correct: 2, explanation: 'The FM-CW radio altimeter sweeps its frequency continuously. The received reflection is slightly delayed; the frequency difference (beat) between the current transmission and the delayed return is proportional to height.' },
    { id: 'rn11_14', question: 'A radio altimeter differs from a barometric altimeter in that it:', options: ['Measures altitude above MSL', 'Is unaffected by QNH setting and measures true height above terrain', 'Measures density altitude', 'Requires ILS to function'], correct: 1, explanation: 'The radio altimeter measures actual height above the ground below, independent of any pressure setting or sea level reference.' },
    { id: 'rn11_15', question: 'For Cat III autoland approaches, the radio altimeter:', options: ['Is optional', 'Provides essential height data to the autopilot/autothrottle', 'Is replaced by barometric altitude at 200 ft', 'Is used only for flare initiation above 100 ft'], correct: 1, explanation: 'In Cat III operations the radio altimeter continuously provides the autopilot with real-time height above ground for approach, flare, and touchdown.' },
    { id: 'rn11_16', question: 'Radio altimeter indications are unreliable:', options: ['During daylight hours only', 'In precipitation and heavy cloud', 'At heights above approximately 2500 ft AGL', 'Only when terrain is below 0°C'], correct: 2, explanation: 'Above approximately 2500 ft AGL the radio altimeter signal becomes unreliable; it is designed for low-level use.' },
    { id: 'rn11_17', question: 'A terrain awareness and warning system (TAWS/GPWS) uses radio altimeter data primarily to:', options: ['Provide ATC with aircraft altitude', 'Generate ground proximity warnings', 'Measure cloud-base height', 'Replace the barometric altimeter'], correct: 1, explanation: 'TAWS/GPWS uses radio altimeter height to generate warnings such as "sink rate", "pull up", and "too low terrain".' },
    { id: 'rn11_18', question: 'The typical range of a radio altimeter is:', options: ['0 to 50,000 ft', '0 to 5,000 ft', '0 to 2,500 ft AGL', '0 to 500 ft only'], correct: 2, explanation: 'Standard radio altimeters are calibrated and accurate from 0 to approximately 2,500 ft AGL.' },
    { id: 'rn11_19', question: 'Why does a radio altimeter use FM-CW rather than pulse radar?', options: ['FM-CW is cheaper to manufacture', 'FM-CW can measure very short distances (low heights) accurately without the minimum range limitation of pulse radar', 'FM-CW is immune to precipitation', 'Pulse radar cannot penetrate cloud'], correct: 1, explanation: 'Pulse radar has a minimum range determined by pulse width; FM-CW has no such limitation, making it suitable for measurement from zero height upward.' },
    { id: 'rn11_20', question: 'A radio altimeter reads 50 ft. This means the aircraft is:', options: ['50 ft above mean sea level', '50 ft above the runway threshold elevation', '50 ft above the terrain or water surface directly below', '50 ft above obstacle clearance height'], correct: 2, explanation: 'Radio altimeter height is absolute terrain clearance — the vertical distance from the aircraft to the surface directly beneath it.' },
    { id: 'rn11_21', question: 'The radio altimeter frequency band of 4200–4400 MHz is allocated to:', options: ['Weather radar', 'Radio altimetry only', 'Air traffic control radar', 'Satellite navigation'], correct: 1, explanation: 'The 4200–4400 MHz band is internationally reserved exclusively for radio altimeters.' },
    { id: 'rn11_22', question: 'A radio altimeter self-test typically shows an indication of:', options: ['Zero', 'Maximum range (2500 ft)', 'A specific test value, typically 0 ft or a fixed low height', 'The barometric altitude'], correct: 2, explanation: 'When the self-test is initiated, the system simulates a signal and displays a specific test height (often 0 ft) to confirm serviceability.' },
    { id: 'rn11_23', question: 'Which of the following is NOT a use of radio altimeter data?', options: ['Autoland flare initiation', 'Cat II/III decision height alerting', 'GPWS ground proximity warning', 'ATC secondary surveillance transponder altitude reporting'], correct: 3, explanation: 'ATC Mode C altitude reporting uses the barometric altimeter (set to 1013.25 hPa), not the radio altimeter.' },
    { id: 'rn11_24', question: 'A radio altimeter with a 10-foot accuracy at 500 ft has an error of:', options: ['10%', '5%', '2%', '0.5%'], correct: 2, explanation: 'Error % = (10/500) × 100 = 2%.' },
    { id: 'rn11_25', question: 'In flight over water, a radio altimeter will:', options: ['Give erroneous readings due to poor reflection', 'Give accurate height above the water surface', 'Not function — it requires land reflection', 'Overread due to specular reflection'], correct: 1, explanation: 'Water is an excellent reflector of radio waves; radio altimeters work well over water and provide accurate height above sea level.' },
    { id: 'rn11_26', question: 'The radio altimeter antenna is normally located:', options: ['On the top of the fuselage, facing upward', 'On the underside of the fuselage, facing downward', 'In the nose cone, facing forward', 'On the tail, facing rearward'], correct: 1, explanation: 'The transmit and receive antennas are mounted on the underside of the fuselage to direct the signal vertically downward.' },
    { id: 'rn11_27', question: 'A radio altimeter is calibrated in:', options: ['Metres above sea level', 'Feet above terrain', 'Feet above MSL', 'Hectopascals'], correct: 1, explanation: 'Radio altimeters read height in feet above the terrain (or water surface) directly below the aircraft.' },
    { id: 'rn11_28', question: 'Two antennas are used in a radio altimeter to:', options: ['Increase range', 'Separate transmit and receive functions to prevent saturation of the receiver', 'Provide redundancy', 'Enable angle measurement'], correct: 1, explanation: 'Separate transmit and receive antennas prevent the powerful transmitted signal from saturating the sensitive receiver.' },
    { id: 'rn11_29', question: 'The Category II ILS minimum decision height (DH) is 100 ft. This DH is referenced to:', options: ['MSL', 'QFE datum', 'Radio altitude above the runway', 'QNH datum'], correct: 2, explanation: 'Cat II DH of 100 ft is measured by the radio altimeter as height above the touchdown zone — radio altitude, not barometric altitude.' },
    { id: 'rn11_30', question: 'A radio altimeter reading will be HIGHER than true height when:', options: ['Flying over a valley (concave terrain)', 'Flying over a hill (convex terrain)', 'Flying straight and level over flat terrain', 'Flying at high speed'], correct: 0, explanation: 'Over a valley, the antenna beam illuminates terrain that is further away than the terrain directly below, giving a higher-than-true height reading.' }
  ],
  rn12: [
    { id: 'rn12_01', question: 'The GPS control segment consists of:', options: ['Satellites and user receivers', 'Master control station, monitor stations, and ground antennas', 'Satellites and master control station only', 'User receivers and ground antennas'], correct: 1, explanation: 'The GPS control segment comprises the Master Control Station (MCS) at Schriever AFB, monitoring stations worldwide, and ground antenna upload stations.' },
    { id: 'rn12_02', question: 'GPS RAIM (Receiver Autonomous Integrity Monitoring) requires a minimum of how many satellites?', options: ['3', '4', '5', '6'], correct: 2, explanation: 'RAIM requires at least 5 satellites to detect a faulty satellite. Fault Exclusion (FDE) requires 6 satellites.' },
    { id: 'rn12_03', question: 'The GPS C/A code (Coarse/Acquisition code) is transmitted at:', options: ['1.023 MHz', '10.23 MHz', '1575.42 MHz', '1227.6 MHz'], correct: 0, explanation: 'The C/A code chip rate is 1.023 Mbps (megachips per second). It is modulated onto the L1 carrier at 1575.42 MHz.' },
    { id: 'rn12_04', question: 'WAAS (Wide Area Augmentation System) improves GPS accuracy to approximately:', options: ['100 m', '25 m', '7.6 m or better', '1 m'], correct: 2, explanation: 'WAAS provides differential corrections via geostationary satellites, improving GPS accuracy to 7.6 m or better (95% of the time).' },
    { id: 'rn12_05', question: 'The GPS P-code (Precise code) is:', options: ['Available to all civil users', 'Reserved for military use and encrypted as the Y-code', 'Used for RAIM calculations only', 'Transmitted on L1 only'], correct: 1, explanation: 'The P-code is the precise military code, encrypted as the P(Y)-code. It has a chip rate of 10.23 Mbps and is transmitted on both L1 and L2.' },
    { id: 'rn12_06', question: 'GPS satellite atomic clocks are accurate to approximately:', options: ['1 second per year', '1 millisecond per day', '20–30 nanoseconds', '1 microsecond per hour'], correct: 2, explanation: 'GPS satellites carry caesium and rubidium atomic clocks accurate to approximately 20–30 nanoseconds, essential for precise pseudo-range measurement.' },
    { id: 'rn12_07', question: 'Pseudo-range in GPS is so named because:', options: ['It is measured in pseudo-nautical miles', 'The receiver clock is not perfectly synchronised with satellite time, introducing a bias', 'It is estimated by averaging multiple ranges', 'The range includes an ionospheric correction estimate'], correct: 1, explanation: 'A pseudo-range is a "false" range — the actual measured distance includes a receiver clock bias error. Four satellites are needed to solve for X, Y, Z, and the clock error.' },
    { id: 'rn12_08', question: 'GLONASS satellites transmit on:', options: ['Different frequencies (FDMA)', 'The same frequency with different codes (CDMA)', '1575.42 MHz only', 'UHF band'], correct: 0, explanation: 'GLONASS uses Frequency Division Multiple Access (FDMA) — each satellite transmits on a different frequency. GPS uses CDMA (same frequency, different codes).' },
    { id: 'rn12_09', question: 'The GNSS signal is most susceptible to interference from:', options: ['Heavy rain and snow', 'Magnetic storms', 'Intentional jamming and multipath reflections', 'High humidity'], correct: 2, explanation: 'GPS signals are low power (-130 dBm at the receiver) and susceptible to intentional jamming and multipath errors from reflections off buildings or terrain.' },
    { id: 'rn12_10', question: 'GPS horizontal accuracy for civil aviation (SPS without SA) is typically:', options: ['300 m (95%)', '100 m (95%)', '15–20 m (95%)', '1 m (95%)'], correct: 2, explanation: 'With Selective Availability switched off (since May 2000), GPS SPS accuracy is typically 15–20 m horizontally (95% of the time).' },
    { id: 'rn12_11', question: 'SBAS (Satellite Based Augmentation System) provides corrections via:', options: ['Geostationary satellites', 'GPS satellites themselves', 'Ground VHF transmitters', 'HF radio broadcasts'], correct: 0, explanation: 'SBAS (e.g. WAAS, EGNOS, GAGAN) broadcasts integrity and differential correction data via geostationary satellites.' },
    { id: 'rn12_12', question: 'EGNOS is the SBAS serving:', options: ['North America', 'Europe', 'Asia Pacific', 'India'], correct: 1, explanation: 'EGNOS (European Geostationary Navigation Overlay Service) is the European SBAS, providing WAAS-equivalent corrections over Europe.' },
    { id: 'rn12_13', question: 'GPS satellite orbits are arranged in how many planes?', options: ['3', '4', '6', '8'], correct: 2, explanation: 'The GPS constellation uses 6 orbital planes with 4 satellites nominally in each, inclined at 55° to the equator.' },
    { id: 'rn12_14', question: 'An almanac in a GPS receiver contains:', options: ['Precise ephemeris data for one satellite', 'Coarse orbital data for all satellites — used to acquire satellites quickly', 'The exact position of the aircraft', 'Ionospheric correction coefficients only'], correct: 1, explanation: 'The almanac contains approximate orbital data for the entire constellation, enabling the receiver to predict which satellites are visible and reduce acquisition time.' },
    { id: 'rn12_15', question: 'An ephemeris in a GPS receiver contains:', options: ['Coarse orbital data for all satellites', 'Precise orbital data for one specific satellite — used for accurate position computation', 'The receiver\'s last known position', 'RAIM confidence data'], correct: 1, explanation: 'The ephemeris contains precise current orbital parameters for a single satellite, used to calculate the satellite\'s exact position for pseudo-range computation.' },
    { id: 'rn12_16', question: 'PDOP (Position Dilution of Precision) measures:', options: ['The effect of satellite geometry on position accuracy', 'The power degradation of GPS signals', 'The phase difference between L1 and L2', 'The probability of RAIM availability'], correct: 0, explanation: 'PDOP quantifies how satellite geometry affects position accuracy. Low PDOP (≤2) means well-spread geometry and good accuracy; high PDOP (>6) means poor geometry.' },
    { id: 'rn12_17', question: 'Ionospheric delay errors on GPS signals are:', options: ['Equal on all frequencies and cannot be corrected', 'Greater on L1 than L2, enabling dual-frequency receivers to model and remove the error', 'Greater at night', 'Negligible below FL100'], correct: 1, explanation: 'Ionospheric delay is frequency-dependent. Dual-frequency receivers (L1 + L2) can calculate and remove ionospheric error, achieving much higher accuracy.' },
    { id: 'rn12_18', question: 'Which augmentation system is used in India?', options: ['WAAS', 'EGNOS', 'GAGAN', 'MSAS'], correct: 2, explanation: 'GAGAN (GPS Aided GEO Augmented Navigation) is the Indian SBAS, operated by ISRO and AAI, covering the Indian FIR.' },
    { id: 'rn12_19', question: 'GPS Fault Detection and Exclusion (FDE) requires a minimum of:', options: ['4 satellites', '5 satellites', '6 satellites', '7 satellites'], correct: 2, explanation: 'FDE requires 6 satellites: 5 for detecting a fault and 1 extra to identify and exclude the faulty satellite, leaving a valid 4-satellite solution.' },
    { id: 'rn12_20', question: 'The GPS navigation message is broadcast at:', options: ['50 bps', '1023 kbps', '10.23 Mbps', '1575.42 MHz'], correct: 0, explanation: 'The GPS navigation message (containing ephemeris, almanac, clock corrections) is modulated at 50 bits per second onto the L1 carrier.' },
    { id: 'rn12_21', question: 'Multipath errors in GPS are caused by:', options: ['Atmospheric scintillation', 'Reflected GPS signals arriving at the receiver in addition to direct signals', 'Satellite clock drift', 'Receiver thermal noise'], correct: 1, explanation: 'Multipath occurs when GPS signals reflect off buildings, terrain, or the aircraft structure and arrive at the antenna by multiple paths, corrupting the pseudo-range.' },
    { id: 'rn12_22', question: 'A GPS receiver determines position by:', options: ['Measuring bearing to each satellite and triangulating', 'Measuring the time of flight of signals from at least 4 satellites to compute pseudo-ranges', 'Comparing the Doppler shift from each satellite', 'Timing the transit of satellites across the sky'], correct: 1, explanation: 'GPS uses the time of arrival of signals from each satellite to compute pseudo-ranges; with 4 satellites the receiver solves simultaneously for latitude, longitude, altitude, and time.' },
    { id: 'rn12_23', question: 'GPS time differs from UTC by:', options: ['Exactly 0 seconds — they are always synchronised', 'A whole number of leap seconds (GPS does not add leap seconds)', '1 hour in summer', 'Varies with solar activity'], correct: 1, explanation: 'GPS time was synchronised to UTC at the start of 1980 and does not include leap seconds. It currently (2026) differs from UTC by 18 seconds.' },
    { id: 'rn12_24', question: 'The L2 GPS frequency (1227.6 MHz) is primarily used for:', options: ['Civil aviation navigation', 'Ionospheric correction in dual-frequency receivers and military P-code', 'Weather monitoring', 'SBAS data transmission'], correct: 1, explanation: 'L2 is used mainly by dual-frequency military and geodetic receivers to measure ionospheric delay. GPS L2C is becoming available for civil use.' },
    { id: 'rn12_25', question: 'A "cold start" of a GPS receiver refers to:', options: ['Starting the receiver in cold temperatures', 'A start with no stored almanac or last-known position, requiring full satellite search', 'Starting after a software update', 'A receiver that has lost lock for less than 30 seconds'], correct: 1, explanation: 'A cold start requires the receiver to search all possible satellite frequencies and PRN codes from scratch, taking several minutes. A warm start uses stored almanac data.' },
    { id: 'rn12_26', question: 'GPS satellite health and status data is uplinked by:', options: ['The user segment (aircraft receivers)', 'The space segment (other satellites)', 'The control segment (ground antennas)', 'The aircraft transponder'], correct: 2, explanation: 'The GPS control segment uploads corrections, clock adjustments, and navigation messages to satellites via dedicated ground antenna stations.' },
    { id: 'rn12_27', question: 'The Galileo satellite navigation system is operated by:', options: ['ESA (European Space Agency) alone', 'The European Union', 'NATO', 'United States Air Force'], correct: 1, explanation: 'Galileo is operated by the European Union (managed by the European Union Agency for the Space Programme, EUSPA).' },
    { id: 'rn12_28', question: 'GPS signals are "spread spectrum" because:', options: ['They are transmitted on multiple frequencies simultaneously', 'The signal power is spread over a wide bandwidth using PRN codes, making it resistant to jamming', 'They are broadcast by multiple satellites', 'The signal spreads over a wide geographic area'], correct: 1, explanation: 'GPS uses spread-spectrum modulation (DSSS) via PRN codes, spreading low-power signals over a wide bandwidth. This provides noise resistance and allows multiple satellites on the same frequency.' },
    { id: 'rn12_29', question: 'The GNSS integrity alert limit for oceanic/en-route aviation is:', options: ['0.1 NM', '1 NM', '2 NM', '12.4 NM'], correct: 3, explanation: 'For oceanic and remote en-route operations, the GNSS integrity alert limit (HAL) is 12.4 NM (2 × 10⁻⁷ probability of missed alert).' },
    { id: 'rn12_30', question: 'When a GPS receiver has RAIM available but fewer than 6 satellites, it can:', options: ['Detect a faulty satellite but cannot exclude it from the solution', 'Both detect and exclude a faulty satellite', 'Neither detect nor exclude a faulty satellite', 'Automatically switch to SBAS mode'], correct: 0, explanation: 'With 5 satellites RAIM can detect (but not exclude) a faulty satellite. Position output will be flagged as unreliable. 6 satellites are needed for fault detection AND exclusion.' }
  ],
  rn13: [
    { id: 'rn13_01', question: 'A Doppler radar measures:', options: ['Slant range to a ground transponder', 'The frequency shift of a radar signal reflected from the ground to derive groundspeed and drift', 'Height above terrain', 'Weather cloud top heights'], correct: 1, explanation: 'Doppler radar uses the change in frequency (Doppler shift) of a transmitted radar signal reflected from the ground to measure the aircraft\'s velocity relative to the ground.' },
    { id: 'rn13_02', question: 'The Doppler effect states that:', options: ['Radio wave frequency is constant regardless of motion', 'When a source or observer is in motion, the received frequency differs from the transmitted frequency', 'Signal amplitude increases with speed', 'Signal attenuation decreases at higher frequencies'], correct: 1, explanation: 'The Doppler effect: a moving source or observer causes the received frequency to be higher (closing) or lower (opening) than the transmitted frequency.' },
    { id: 'rn13_03', question: 'A Doppler radar system operates in which frequency band?', options: ['HF (3–30 MHz)', 'VHF (30–300 MHz)', 'UHF (300–3000 MHz)', 'SHF (3–30 GHz)'], correct: 3, explanation: 'Airborne Doppler radars operate in the SHF (microwave) band, typically around 8.8 GHz (X-band) or 13.3 GHz (Ku-band).' },
    { id: 'rn13_04', question: 'Doppler radar beams are directed:', options: ['Vertically downward', 'Forward and downward at an angle, typically in a 3 or 4 beam configuration', 'Horizontally to weather cells', 'Rearward to measure acceleration'], correct: 1, explanation: 'Doppler radar transmits beams forward and downward at a fixed depression angle, arranged in 3 or 4 directions to resolve fore/aft and lateral velocity components.' },
    { id: 'rn13_05', question: 'Which of the following can a Doppler radar directly measure?', options: ['Groundspeed and drift angle', 'True airspeed and altitude', 'Magnetic heading and variation', 'Latitude and longitude'], correct: 0, explanation: 'Doppler radar measures groundspeed (fore-aft component) and drift angle (lateral component) by analysing Doppler frequency shifts in multiple beams.' },
    { id: 'rn13_06', question: 'Doppler radar groundspeed measurement becomes unreliable:', options: ['At altitudes above 10,000 ft', 'Over smooth water or very smooth terrain where specular reflection scatters the signal', 'In moderate turbulence', 'At high Mach numbers'], correct: 1, explanation: 'Over calm water or very smooth terrain, radar energy is reflected away from the aircraft (specular reflection) rather than being scattered back. This is called the "water gap" or "smooth water error."' },
    { id: 'rn13_07', question: 'The Doppler frequency shift (Δf) is proportional to:', options: ['Signal amplitude and wavelength', 'Aircraft velocity and cosine of beam depression angle divided by signal wavelength', 'Aircraft altitude only', 'Signal attenuation and frequency'], correct: 1, explanation: 'Δf = (2V × cosθ) / λ where V = velocity, θ = angle between beam and horizontal, λ = wavelength. The factor of 2 accounts for both outgoing and returning paths.' },
    { id: 'rn13_08', question: 'A Janus configuration in Doppler radar means:', options: ['Two antennas, one forward and one backward, aligned on the aircraft axis', 'Beams are transmitted both forward and aft (and optionally left/right), in a cruciform pattern', 'The radar transmits pulses rather than continuous waves', 'A single rotating antenna is used'], correct: 1, explanation: 'The Janus (two-faced) configuration uses paired forward and aft beams. Comparing returns from both cancels out pitch and roll attitude errors, improving accuracy.' },
    { id: 'rn13_09', question: 'A Doppler radar system with 4-beam Janus configuration provides:', options: ['Only groundspeed', 'Groundspeed and drift angle, with pitch/roll error cancellation', 'Altitude, groundspeed and drift', 'Heading and groundspeed only'], correct: 1, explanation: 'A 4-beam Janus system provides groundspeed and drift angle; pitch and roll attitude changes are automatically cancelled.' },
    { id: 'rn13_10', question: 'The principal advantage of Doppler radar over INS for self-contained navigation is:', options: ['Doppler radar does not have position drift errors with time', 'Doppler radar is more accurate in pitch and roll', 'Doppler radar requires no initial alignment', 'Doppler radar works better over polar regions'], correct: 0, explanation: 'Doppler radar velocity measurement errors do not accumulate with time; INS position errors grow over time due to integration of small accelerometer biases.' },
    { id: 'rn13_11', question: 'Doppler radar requires which initial data input to begin navigation?', options: ['Atmospheric pressure', 'A magnetic heading reference and a starting position (latitude/longitude)', 'ILS frequency', 'ATC clearance'], correct: 1, explanation: 'Doppler radar provides velocity; to compute track and position it needs an initial position (lat/long) and a heading reference from the compass system.' },
    { id: 'rn13_12', question: 'The Doppler radar "memory" mode activates when:', options: ['The aircraft lands', 'The signal lock is lost (e.g. over smooth water)', 'The aircraft exceeds maximum range', 'The heading reference fails'], correct: 1, explanation: 'When Doppler lock is lost, the system enters memory mode, maintaining the last measured velocity values to continue navigation until lock is regained.' },
    { id: 'rn13_13', question: 'Over which surface does a Doppler radar work BEST?', options: ['Smooth calm water', 'Flat featureless desert', 'Rough sea or forested terrain (diffuse reflectors)', 'Ice sheets'], correct: 2, explanation: 'Doppler radar requires diffuse (non-specular) reflection; rough sea, forests, and irregular terrain scatter radar energy back to the aircraft effectively.' },
    { id: 'rn13_14', question: 'The Doppler frequency shift for an aircraft flying at 400 kt using a 13.3 GHz radar at a 65° depression angle will be approximately:', options: ['1 kHz', '7.5 kHz', '3.4 kHz', '15 kHz'], correct: 1, explanation: 'Doppler shift = 2 x V x cos(theta) / wavelength. V = 400 kt = 205.8 m/s, wavelength = 3e8/13.3e9 = 0.0226 m, cos65 = 0.423, giving about 7.5 kHz.' },
    { id: 'rn13_15', question: 'A Doppler radar navigation system is classified as:', options: ['A dependent navigation system', 'A primary radio navigation aid', 'A self-contained dead reckoning system', 'A precision approach aid'], correct: 2, explanation: 'Doppler radar is self-contained — it does not depend on external ground stations. It is a dead reckoning system, continuously computing position from measured velocity.' },
    { id: 'rn13_16', question: 'Which of the following errors is specific to Doppler radar over water?', options: ['Quadrantal error', 'Specular reflection causing loss of ground return', 'Coastal refraction of the radar beam', 'Night effect from ionospheric reflections'], correct: 1, explanation: 'The "water gap" or smooth water error occurs because calm water acts as a mirror (specular reflector), reflecting energy away from the receiver, causing signal loss.' },
    { id: 'rn13_17', question: 'In a Doppler system, drift angle is measured as:', options: ['The angle between true heading and magnetic heading', 'The angle between aircraft heading and track made good, derived from lateral beam frequency differences', 'The angle of beam depression below horizontal', 'The bearing to the next waypoint'], correct: 1, explanation: 'Drift angle is the angle between heading and track. Doppler derives it from the frequency shift in the lateral (sideways) beam components compared to the fore-aft components.' },
    { id: 'rn13_18', question: 'The wavelength used in an 8.8 GHz Doppler radar is approximately:', options: ['3.4 cm', '8.8 cm', '1.1 cm', '33 mm'], correct: 0, explanation: 'λ = c/f = 3×10¹⁰ / 8.8×10⁹ ≈ 3.41 cm. Shorter wavelengths give larger Doppler shifts for a given speed, improving resolution.' },
    { id: 'rn13_19', question: 'Doppler radar altitude error occurs because:', options: ['The system measures height above MSL, not terrain', 'Pitch attitude changes the beam angle and hence the Doppler frequency shift', 'The radar beam bends in a temperature inversion', 'The radar frequency drifts with temperature'], correct: 1, explanation: 'Without a Janus configuration, pitch attitude changes alter the beam depression angle, changing the Doppler shift for the same groundspeed. Janus cancels this error.' },
    { id: 'rn13_20', question: 'Compared to GPS, a Doppler navigation system:', options: ['Is more accurate globally', 'Is self-contained and not subject to jamming or signal denial', 'Provides better altitude information', 'Requires no initial position data'], correct: 1, explanation: 'Doppler radar is entirely self-contained and does not rely on signals from external sources (satellites or ground stations), making it immune to jamming or signal denial.' },
    { id: 'rn13_21', question: 'A Doppler radar system integrates velocity to give:', options: ['Altitude above terrain', 'Track, distance travelled, and position relative to starting point', 'Heading and wind velocity', 'Weather return echoes'], correct: 1, explanation: 'By continuously integrating measured velocity components (fore-aft and lateral), the system computes track and distance flown, and hence present position.' },
    { id: 'rn13_22', question: 'The factor of 2 appears in the Doppler shift formula (Δf = 2Vcosθ/λ) because:', options: ['Two antennas are used', 'The signal travels to the ground AND back — the path length changes twice for each unit of movement', 'Janus configuration uses two beams', 'The frequency is doubled at the receiver'], correct: 1, explanation: 'The signal closes at rate Vcosθ on the outward path and again on the return path. Both contribute to the frequency shift, hence the factor of 2.' },
    { id: 'rn13_23', question: 'Which of the following best describes the operating frequency of an airborne Doppler navigation radar?', options: ['108–118 MHz (VHF)', '329–335 MHz (UHF)', '8.8 GHz or 13.3 GHz (SHF/microwave)', '76 GHz (EHF)'], correct: 2, explanation: 'Airborne Doppler navigation radars operate in the microwave (SHF) band, commonly 8.8 GHz (X-band) or 13.3 GHz (Ku-band).' },
    { id: 'rn13_24', question: 'A Doppler radar system gives a groundspeed reading of 450 kt. The aircraft\'s INS shows 460 kt. The most likely cause of the difference is:', options: ['The Doppler radar is measuring TAS, not groundspeed', 'The Doppler radar is experiencing partial loss of return over smooth terrain, causing the velocity to read low', 'The INS is measuring drift-corrected speed', 'The magnetic variation has been applied incorrectly'], correct: 1, explanation: 'Partial specular reflection (e.g. over smooth water or flat terrain) can reduce the signal strength and shift the measured Doppler frequency, causing groundspeed to read low.' },
    { id: 'rn13_25', question: 'Doppler radar accuracy in heading is achieved by:', options: ['Using the Doppler radar itself as a heading reference', 'Slaving the Doppler computations to the aircraft\'s directional gyro or INS heading', 'Using magnetic variation at the aircraft position', 'Aligning with GPS track over time'], correct: 1, explanation: 'Doppler radar measures velocity components but cannot measure heading independently; it relies on the aircraft\'s heading reference system (DGI, INS, or compass) for track computation.' },
    { id: 'rn13_26', question: 'Position errors in Doppler navigation accumulate because:', options: ['Velocity errors are integrated over time', 'The radar signal drifts at a rate of 0.5° per hour', 'Magnetic variation changes along the route', 'The system cannot measure height changes'], correct: 0, explanation: 'Any small constant velocity error (e.g. from beam geometry error or scale factor error) is integrated over time to produce a growing position error — a characteristic of all dead reckoning systems.' },
    { id: 'rn13_27', question: 'The "look angle" or depression angle of a Doppler radar beam is typically:', options: ['90° (vertically downward)', '65° to 70° below horizontal', '30° to 45° below horizontal', '10° below horizontal'], correct: 2, explanation: 'Doppler radar beams are typically depressed 65°–70° from horizontal (or equivalently, 20°–25° from vertical), giving a good balance between Doppler sensitivity and signal return strength.' },
    { id: 'rn13_28', question: 'Doppler radar is used in combination with INS or GPS primarily to:', options: ['Calibrate the GPS receiver', 'Update position during GPS outages and reduce INS drift errors', 'Provide weather avoidance information', 'Measure crosswind component for landing'], correct: 1, explanation: 'Doppler/INS integration uses Doppler groundspeed and drift to bound and correct INS drift errors, providing a more reliable combined navigation solution during GPS outages.' },
    { id: 'rn13_29', question: 'The Doppler radar returns useful signal from:', options: ['Moving targets on the ground', 'Stationary ground features that reflect the radar beam back to the aircraft', 'Clouds and precipitation only', 'Other aircraft ahead'], correct: 1, explanation: 'Doppler navigation radar relies on ground clutter — reflections from stationary terrain features. The frequency shift of these returns is due solely to aircraft motion.' },
    { id: 'rn13_30', question: 'A Doppler radar system is described as "coherent" because:', options: ['All four beams transmit simultaneously', 'The receiver maintains a phase reference to the transmitted signal, enabling precise frequency shift measurement', 'The system uses digital signal processing', 'The transmitter and receiver share the same antenna'], correct: 1, explanation: 'A coherent radar maintains phase coherence between the transmitted and received signals, which is essential for accurate measurement of the small Doppler frequency shifts involved.' }
  ],

}

export const chapters = DEFINITIONS.map((definition) => ({
  id: definition.id,
  title: definition.title,
  icon: definition.icon,
  part: definition.part,
  color: definition.color,
}))

export const questions = Object.fromEntries(
  chapters.map((chapter, chapterIndex) => [chapter.id, [...buildQuestions(chapter, chapterIndex), ...(EXTRA_QUESTIONS[chapter.id] || [])]])
)
